// NEET UG Biology: Breathing and exchange of gases (NCERT Class 11, Chapter 14). All questions original fibub work.
import { pick, int, choose, fmt, shuffleOpts, numOpts, g } from '../_entrance.js';

const E = ['neet'];
const items = [];
const groups = {};
let n = 0, pos = 0;
const POS = [1, 3, 0, 2];
const nid = () => `br-${String(++n).padStart(3, '0')}`;
const AR = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const ST = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'];
function mc(level, sub, q, correct, wrongs, sol, trap, format = 'single') {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format, exams: E, sub, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function asr(level, sub, A, R, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'assertion', exams: E, sub, q: `<b>Assertion (A):</b> ${A}<br><b>Reason (R):</b> ${R}`, options: AR, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function stm(level, sub, s1, s2, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: E, sub, q: `<b>Statement I:</b> ${s1}<br><b>Statement II:</b> ${s2}`, options: ST, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function match(level, sub, key, title, list1, list2, correct, wrongs, sol, trap) {
  groups[key] = { title, list1, list2 };
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: E, sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function pass(key, title, passage) { groups[key] = { title, passage }; }
function pq(key, level, sub, q, correct, wrongs, sol, trap) {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'passage', exams: E, sub, group: key, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}

// ---------------------------------------------------------------- Level 1
mc(1, 'respiratory organs', 'Gaseous exchange in bony fishes takes place through', 'gills', ['lungs', 'tracheal tubes', 'moist cuticle'], 'Fishes use gills, which are vascularised structures that exchange gases between the water and the blood.');
mc(1, 'respiratory organs', 'An earthworm exchanges gases mainly through its', 'moist cuticle', ['gills', 'tracheal tubes', 'lungs'], 'Earthworms are annelids and breathe through the moist cuticle of the body wall.');
mc(1, 'respiratory organs', 'Insects carry air to their tissues through a network of', 'tracheal tubes', ['gills', 'book lungs only', 'bronchi'], 'In insects air goes through tracheae, a network of tubes that reach the tissues directly.');
mc(1, 'respiratory organs', 'Sponges, coelenterates and flatworms exchange O<sub>2</sub> and CO<sub>2</sub> by', 'simple diffusion over the whole body surface', ['gills', 'lungs', 'tracheal tubes'], 'These simple animals have no special organs. Gases diffuse directly through the body surface.');
mc(1, 'respiratory organs', 'Which of these animals breathes with lungs?', 'Reptiles, birds and mammals', ['Fishes and prawns', 'Earthworm and leech', 'Cockroach and locust'], 'Reptiles, birds and mammals respire through lungs. Fishes use gills, annelids use the skin and insects use tracheae.');
mc(1, 'human respiratory system', 'The voice box in humans is the', 'larynx', ['pharynx', 'trachea', 'glottis'], 'The larynx is a cartilaginous box that helps in sound production, so it is called the sound box.');
mc(1, 'human respiratory system', 'The flap that covers the glottis during swallowing is the', 'epiglottis', ['uvula', 'tonsil', 'diaphragm'], 'The epiglottis prevents the entry of food into the larynx.');
mc(1, 'human respiratory system', 'The main site of exchange of gases in the lungs is the', 'alveoli', ['trachea', 'bronchi', 'pharynx'], 'Alveoli are thin, vascularised bag-like structures. They are the primary sites of gas exchange.');
mc(1, 'human respiratory system', 'The lungs are covered by a', 'double-layered pleura', ['single-layered pericardium', 'peritoneum', 'periosteum'], 'Pleura has two layers, with pleural fluid between them that reduces friction on the lung surface.');
mc(1, 'mechanism of breathing', 'The main muscle that helps in inspiration is the', 'diaphragm', ['biceps', 'rectus abdominis', 'trapezius'], 'The diaphragm, along with the external intercostal muscles, creates the pressure gradient needed for inspiration.');
mc(1, 'mechanism of breathing', 'The normal rate of breathing in a healthy human at rest is about', '12 to 16 times per minute', ['2 to 4 times per minute', '30 to 40 times per minute', '72 times per minute'], 'A healthy person breathes 12-16 times a minute. 72 is the heart rate, not breathing rate.', 'Heart rate and breathing rate are often mixed.');
mc(1, 'transport of gases', 'The red pigment that carries most of the oxygen in blood is', 'haemoglobin', ['myoglobin', 'melanin', 'chlorophyll'], 'Haemoglobin is an iron-containing pigment in RBCs. It binds O<sub>2</sub> reversibly to form oxyhaemoglobin.');
mc(1, 'transport of gases', 'How many oxygen molecules can one haemoglobin molecule carry at the most?', 'Four', ['One', 'Two', 'Eight'], 'Haemoglobin has four haem groups, each with an iron atom, so one molecule carries up to four O<sub>2</sub> molecules.');
mc(1, 'transport of gases', 'The enzyme that speeds up the reaction between CO<sub>2</sub> and water in RBCs is', 'carbonic anhydrase', ['carboxylase', 'catalase', 'amylase'], 'Carbonic anhydrase makes CO<sub>2</sub> + H<sub>2</sub>O into H<sub>2</sub>CO<sub>3</sub> very fast, and also reverses the reaction in the alveoli.');
mc(1, 'regulation of respiration', 'The respiratory rhythm centre is found in the', 'medulla oblongata', ['cerebrum', 'cerebellum', 'spinal cord'], 'The rhythm centre in the medulla is mainly responsible for the rhythm of breathing.');
mc(1, 'disorders', 'A chronic disorder in which alveolar walls are damaged, mainly by smoking, is', 'emphysema', ['asthma', 'silicosis', 'pneumonia'], 'In emphysema the respiratory surface is decreased because alveolar walls break down. Cigarette smoking is the major cause.');
mc(1, 'disorders', 'Wheezing and difficulty in breathing caused by inflammation of bronchi and bronchioles is called', 'asthma', ['emphysema', 'asbestosis', 'tuberculosis'], 'Asthma is the inflammation of the bronchi and bronchioles, which makes breathing difficult with a wheezing sound.');
mc(1, 'human respiratory system', 'The trachea and bronchi are kept open by', 'incomplete rings of cartilage', ['complete rings of bone', 'smooth muscle only', 'ligaments'], 'Trachea, primary, secondary and tertiary bronchi and the initial bronchioles are supported by incomplete cartilaginous rings so that they do not collapse.');
mc(1, 'respiratory volumes', 'The volume of air inspired or expired in a normal quiet breath is called', 'tidal volume', ['vital capacity', 'residual volume', 'total lung capacity'], 'Tidal volume (TV) is about 500 mL in a healthy adult.');
mc(1, 'mechanism of breathing', 'During inspiration the pressure inside the lungs (intra-pulmonary pressure) is', 'less than the atmospheric pressure', ['equal to the atmospheric pressure', 'greater than the atmospheric pressure', 'zero'], 'Air flows in only when the lung pressure falls below the atmospheric pressure. The thoracic volume must increase for this.');

// ---------------------------------------------------------------- Level 2
mc(2, 'respiratory volumes', 'The maximum volume of air a person can breathe out after a forced deep inspiration is the', 'vital capacity', ['total lung capacity', 'functional residual capacity', 'inspiratory capacity'], 'Vital capacity (VC) = ERV + TV + IRV. It is the largest air volume that can be moved out after a maximal inspiration.');
mc(2, 'respiratory volumes', 'Inspiratory capacity is the sum of', 'tidal volume and inspiratory reserve volume', ['tidal volume and expiratory reserve volume', 'expiratory reserve volume and residual volume', 'inspiratory reserve volume and residual volume'], 'IC = TV + IRV. It is the air a person can inspire starting from the normal expiratory level.');
mc(2, 'respiratory volumes', 'Functional residual capacity is the sum of', 'expiratory reserve volume and residual volume', ['tidal volume and residual volume', 'inspiratory reserve volume and tidal volume', 'vital capacity and residual volume'], 'FRC = ERV + RV. It is the air left in the lungs at the end of a normal expiration.', 'TLC = VC + RV, not FRC.');
mc(2, 'respiratory volumes', 'The air that remains in the lungs even after a forcible expiration is the', 'residual volume', ['expiratory reserve volume', 'tidal volume', 'inspiratory capacity'], 'Residual volume is about 1100 to 1200 mL. It cannot be breathed out.');
mc(2, 'respiratory volumes', 'Expiratory reserve volume is the', 'extra air that can be forcibly expired after a normal expiration', ['extra air that can be forcibly inspired after a normal inspiration', 'air left after forced expiration', 'air breathed in at rest'], 'ERV is about 1000 to 1100 mL. The extra air taken in after a normal inspiration is IRV.');
mc(2, 'respiratory volumes', 'Total lung capacity is', 'vital capacity plus residual volume', ['tidal volume plus residual volume', 'inspiratory capacity plus tidal volume', 'expiratory capacity alone'], 'TLC is the total volume of air in the lungs after a forced inspiration: VC + RV, which is about 5000 to 6000 mL.');
mc(2, 'exchange of gases', 'About what percentage of CO<sub>2</sub> is transported as bicarbonate?', '70 per cent', ['7 per cent', '20 to 25 per cent', '97 per cent'], 'About 70% is carried as bicarbonate, 20 to 25% as carbamino-haemoglobin and about 7% is dissolved in plasma.', '97% is the oxygen on haemoglobin.');
mc(2, 'transport of gases', 'What percentage of oxygen is carried dissolved in the plasma?', '3 per cent', ['7 per cent', '20 per cent', '97 per cent'], 'About 97% of O<sub>2</sub> is carried by RBCs bound to haemoglobin. Only about 3% is dissolved in plasma.');
mc(2, 'transport of gases', 'Carbon dioxide bound to haemoglobin is called', 'carbamino-haemoglobin', ['oxyhaemoglobin', 'carboxyhaemoglobin', 'methaemoglobin'], 'CO<sub>2</sub> binds to the amino groups of the globin part, forming carbamino-haemoglobin. Carboxyhaemoglobin is with carbon monoxide.', 'Carbamino and carboxy sound alike.');
mc(2, 'exchange of gases', 'The partial pressure of oxygen (pO<sub>2</sub>) in alveolar air is about', '104 mm Hg', ['159 mm Hg', '40 mm Hg', '45 mm Hg'], 'pO<sub>2</sub> is 159 in atmospheric air, 104 in alveoli, 95 in oxygenated blood and 40 in deoxygenated blood and tissues.');
mc(2, 'exchange of gases', 'The partial pressure of CO<sub>2</sub> in the tissues is about', '45 mm Hg', ['0.3 mm Hg', '40 mm Hg', '104 mm Hg'], 'Tissues have pCO<sub>2</sub> of 45 mm Hg. In alveoli it is 40, so CO<sub>2</sub> moves from tissues into blood and then into alveoli.');
mc(2, 'exchange of gases', 'CO<sub>2</sub> can diffuse across the alveolar membrane even with a small pressure gradient because', 'it is 20 to 25 times more soluble than O<sub>2</sub>', ['it is a lighter gas than O<sub>2</sub>', 'it is lipid-insoluble', 'it moves by active transport'], 'The solubility of CO<sub>2</sub> is 20-25 times that of O<sub>2</sub>, so a smaller gradient is enough for the same diffusion.');
mc(2, 'exchange of gases', 'The diffusion membrane in the lung is made of how many layers?', 'Three', ['One', 'Two', 'Five'], 'The thin squamous epithelium of the alveoli, the endothelium of the alveolar capillaries and the basement substance between them make three layers. The total thickness is less than a millimetre.');
mc(2, 'human respiratory system', 'The trachea divides into right and left primary bronchi at about the level of the', 'fifth thoracic vertebra', ['first cervical vertebra', 'second lumbar vertebra', 'tenth thoracic vertebra'], 'The trachea is a straight tube that extends up to the mid-thoracic cavity, where it divides at the 5th thoracic vertebra.');
mc(2, 'regulation of respiration', 'The pneumotaxic centre is located in the', 'pons region of the brain', ['medulla oblongata', 'cerebellum', 'hypothalamus'], 'The pneumotaxic centre in the pons can moderate the rhythm centre. A signal from it can reduce the duration of inspiration.');
mc(2, 'regulation of respiration', 'The chemosensitive area near the rhythm centre is highly sensitive to', 'CO<sub>2</sub> and hydrogen ions', ['O<sub>2</sub> and glucose', 'nitrogen and water', 'only O<sub>2</sub>'], 'An increase in CO<sub>2</sub> and H<sup>+</sup> activates this area, and it signals the rhythm centre to change the breathing so that they are removed.');
mc(2, 'mechanism of breathing', 'Normal expiration is mostly a passive process because it needs', 'only relaxation of the diaphragm and external intercostal muscles', ['strong contraction of the diaphragm', 'contraction of the abdominal muscles', 'contraction of the external intercostals'], 'On relaxation the diaphragm and sternum return to their normal position and the thoracic volume decreases, so air is pushed out.');
mc(2, 'mechanism of breathing', 'During inspiration the dorso-ventral axis of the thorax increases because of the', 'contraction of the external intercostal muscles', ['relaxation of the diaphragm', 'contraction of the internal intercostals', 'relaxation of the abdominal muscles'], 'External intercostals lift the ribs and sternum, which increases the dorso-ventral axis. The diaphragm increases the antero-posterior axis.');
mc(2, 'respiratory volumes', 'A person breathes 500 mL of air per breath, 12 times a minute. The volume of air that moves in and out in a minute is', '6000 mL', ['500 mL', '1200 mL', '12000 mL'], 'Volume per minute = tidal volume × rate = 500 × 12 = 6000 mL.');
mc(2, 'transport of gases', 'Under normal conditions, every 100 mL of oxygenated blood delivers about how much O<sub>2</sub> to the tissues?', '5 mL', ['0.5 mL', '20 mL', '97 mL'], 'NCERT states that 100 mL of oxygenated blood can deliver around 5 mL of O<sub>2</sub> to tissues under normal conditions.');
mc(2, 'transport of gases', 'Every 100 mL of deoxygenated blood delivers about how much CO<sub>2</sub> to the alveoli?', '4 mL', ['0.4 mL', '40 mL', '70 mL'], 'It is about 4 mL of CO<sub>2</sub> for each 100 mL of deoxygenated blood.');
mc(2, 'regulation of respiration', 'Which gas has an insignificant role in the regulation of respiration?', 'O<sub>2</sub>', ['CO<sub>2</sub>', 'H<sup>+</sup> ions', 'None; all three matter equally'], 'The role of O<sub>2</sub> in the regulation of the respiratory rhythm is quite insignificant. CO<sub>2</sub> and H<sup>+</sup> are the main signals.');
mc(2, 'disorders', 'Silicosis and asbestosis are', 'occupational respiratory disorders', ['hereditary disorders of the lungs', 'bacterial diseases', 'disorders of the larynx'], 'Long exposure to silica or asbestos dust in grinding and stone-breaking industries causes inflammation and fibrosis, and serious lung damage.');
mc(2, 'human respiratory system', 'Which of these is part of the conducting zone but NOT the exchange region?', 'Terminal bronchiole', ['Alveolus', 'Alveolar duct', 'Respiratory bronchiole region with alveoli'], 'The conducting part runs from the external nostrils to the terminal bronchioles. It carries, filters, humidifies and warms air. Alveoli do the exchange.');
mc(2, 'respiratory organs', 'The respiratory organ of a prawn is the', 'gill', ['tracheal tube', 'lung', 'moist skin'], 'Aquatic arthropods and molluscs have vascularised gills.');
mc(2, 'respiratory organs', 'Frogs can breathe through the', 'moist skin as well as the lungs', ['gills only', 'lungs only', 'tracheae'], 'Amphibians such as frogs use lungs on land and also exchange gases through the moist skin (cutaneous respiration).');
mc(2, 'human respiratory system', 'The air passes from the nasal chamber to the larynx through the', 'nasopharynx', ['oesophagus', 'bronchiole', 'alveolar duct'], 'The nasal chamber opens to the nasopharynx, through which air enters the glottis and larynx.');
mc(2, 'exchange of gases', 'The partial pressure of oxygen in deoxygenated blood is about', '40 mm Hg', ['95 mm Hg', '104 mm Hg', '159 mm Hg'], 'Deoxygenated blood arriving at the lungs has pO<sub>2</sub> of 40 and pCO<sub>2</sub> of 45 mm Hg.');
mc(2, 'mechanism of breathing', 'The lungs follow the movement of the chest wall because', 'the thoracic cavity is air-tight and the lungs are held to it by the pleural fluid', ['the lungs have their own muscles', 'the lungs are fixed to the ribs by cartilage', 'air in the pleura pushes the lungs'], 'The lungs have no muscles of their own. The pleural layers with fluid between them make the lung surface follow the thoracic cavity.');

// ---------------------------------------------------------------- Level 3
mc(3, 'respiratory volumes', 'In a person ERV = 1100 mL, TV = 500 mL and IRV = 3000 mL. The vital capacity is', '4600 mL', ['3500 mL', '3600 mL', '5800 mL'], 'VC = ERV + TV + IRV = 1100 + 500 + 3000 = 4600 mL.', '5800 mL would be TLC if RV were 1200 mL.');
mc(3, 'respiratory volumes', 'A person has VC = 4600 mL and RV = 1200 mL. The total lung capacity is', '5800 mL', ['3400 mL', '4600 mL', '6900 mL'], 'TLC = VC + RV = 4600 + 1200 = 5800 mL.');
mc(3, 'respiratory volumes', 'ERV = 1000 mL and RV = 1200 mL. The functional residual capacity is', '2200 mL', ['200 mL', '1700 mL', '2700 mL'], 'FRC = ERV + RV = 1000 + 1200 = 2200 mL.');
mc(3, 'respiratory volumes', 'TV = 500 mL and IRV = 2500 mL. The inspiratory capacity is', '3000 mL', ['2000 mL', '2500 mL', '3500 mL'], 'IC = TV + IRV = 500 + 2500 = 3000 mL.');
mc(3, 'respiratory volumes', 'The expiratory capacity (TV + ERV) of a person with TV = 500 mL and ERV = 1100 mL is', '1600 mL', ['600 mL', '1100 mL', '3600 mL'], 'EC = TV + ERV = 500 + 1100 = 1600 mL. It is the air that can be expired from the normal inspiratory level.');
mc(3, 'respiratory volumes', 'Which of these CANNOT be measured by a simple spirometer?', 'Residual volume', ['Tidal volume', 'Inspiratory reserve volume', 'Expiratory reserve volume'], 'A spirometer records air moved in and out. RV remains in the lungs, so it, and capacities that include it (FRC, TLC), cannot be read directly.', 'FRC and TLC also contain RV.');
mc(3, 'respiratory volumes', 'Which expression gives the total lung capacity?', 'TV + IRV + ERV + RV', ['TV + IRV + ERV', 'TV + ERV + RV', 'IRV + ERV + RV'], 'TLC = VC + RV = (TV + IRV + ERV) + RV. All four volumes make the total.');
mc(3, 'respiratory volumes', 'Which of the following capacities does NOT include the residual volume?', 'Vital capacity', ['Functional residual capacity', 'Total lung capacity', 'FRC and TLC both'], 'VC = ERV + TV + IRV, with no RV. FRC and TLC contain RV.');
mc(3, 'transport of gases', 'Which condition favours the formation of oxyhaemoglobin?', 'High pO<sub>2</sub>, low pCO<sub>2</sub>, lower H<sup>+</sup> and lower temperature', ['Low pO<sub>2</sub>, high pCO<sub>2</sub>, high H<sup>+</sup> and high temperature', 'High pO<sub>2</sub>, high pCO<sub>2</sub> and high temperature', 'Low pO<sub>2</sub> and low temperature'], 'These are the alveolar conditions, which load haemoglobin. The opposite set, as in tissues, helps unloading.', 'Mixing one tissue factor with alveolar factors.');
mc(3, 'transport of gases', 'In the oxygen dissociation curve, the factor of greatest importance in the binding of O<sub>2</sub> to haemoglobin is', 'partial pressure of oxygen', ['partial pressure of nitrogen', 'concentration of glucose', 'blood volume'], 'The binding is mainly related to pO<sub>2</sub>. pCO<sub>2</sub>, H<sup>+</sup> concentration and temperature are the other factors that interfere.');
mc(3, 'transport of gases', 'The oxygen dissociation curve of haemoglobin is', 'sigmoid', ['a straight line', 'a hyperbola', 'a parabola'], 'A graph of per cent saturation of Hb against pO<sub>2</sub> is S-shaped (sigmoid), because binding of the first O<sub>2</sub> makes the later ones easier.');
mc(3, 'transport of gases', 'In active muscles, a rise in temperature and acidity makes the oxygen dissociation curve', 'shift to the right, so more O<sub>2</sub> is released', ['shift to the left, so more O<sub>2</sub> is held', 'turn into a straight line', 'remain unchanged'], 'More CO<sub>2</sub>, more H<sup>+</sup> and more heat decrease the affinity of Hb for O<sub>2</sub> (Bohr effect), which releases more oxygen to working tissues.', 'A right shift means LOWER affinity.');
mc(3, 'transport of gases', 'A left shift of the oxygen dissociation curve is seen in the', 'alveoli, where pCO<sub>2</sub> and H<sup>+</sup> are lower', ['active muscles', 'tissues with high temperature', 'tissues with low pH'], 'In the alveoli Hb has more affinity for O<sub>2</sub>. The curve shifts left and haemoglobin loads easily.');
mc(3, 'transport of gases', 'Which of the following reactions occurs at the alveolar level?', 'HCO<sub>3</sub><sup>-</sup> + H<sup>+</sup> &rarr; H<sub>2</sub>CO<sub>3</sub> &rarr; CO<sub>2</sub> + H<sub>2</sub>O', ['CO<sub>2</sub> + H<sub>2</sub>O &rarr; H<sub>2</sub>CO<sub>3</sub> &rarr; HCO<sub>3</sub><sup>-</sup> + H<sup>+</sup>', 'Hb + O<sub>2</sub> &rarr; HbO<sub>2</sub> only', 'CO<sub>2</sub> + Hb &rarr; carbamino-haemoglobin'], 'In the alveoli pCO<sub>2</sub> is low, so the reaction goes in the reverse direction and CO<sub>2</sub> is released from bicarbonate. The forward reaction is in the tissues.', 'The same enzyme works in both directions.');
mc(3, 'exchange of gases', 'The pCO<sub>2</sub> of oxygenated blood leaving the lungs is about', '40 mm Hg', ['45 mm Hg', '104 mm Hg', '0.3 mm Hg'], 'Oxygenated blood has pO<sub>2</sub> of about 95 and pCO<sub>2</sub> of about 40 mm Hg.');
mc(3, 'exchange of gases', 'The partial pressure gradient for O<sub>2</sub> from the alveoli (104) to the deoxygenated blood (40) is', '64 mm Hg', ['5 mm Hg', '145 mm Hg', '119 mm Hg'], '104 - 40 = 64 mm Hg. The gradient for CO<sub>2</sub> in the other direction is 45 - 40 = 5 mm Hg.');
mc(3, 'regulation of respiration', 'Peripheral receptors that sense changes in CO<sub>2</sub> and H<sup>+</sup> are found in the', 'aortic arch and carotid artery', ['pulmonary vein and vena cava', 'alveolar wall and bronchioles', 'diaphragm and intercostals'], 'Receptors in the aortic arch and carotid artery recognise changes in CO<sub>2</sub> and H<sup>+</sup> concentration and send signals to the rhythm centre.');
mc(3, 'regulation of respiration', 'The pneumotaxic centre, if its signal is strengthened, will', 'shorten inspiration and so increase the rate of breathing', ['lengthen inspiration and decrease the rate', 'stop expiration', 'have no effect on the rate'], 'The pneumotaxic centre moderates the inspiratory rhythm centre. A signal that shortens inspiration makes each breath shorter and the rate faster.');
mc(3, 'disorders', 'Which of the following is correct about emphysema?', 'Alveolar walls are damaged, so the respiratory surface decreases', ['It is an allergic inflammation of the bronchi', 'It is caused only by silica dust', 'It increases the surface area of the lungs'], 'The damaged alveoli reduce the area for gas exchange. Inflammation of bronchi is asthma.');
mc(3, 'disorders', 'Fibrosis of the lungs due to long exposure to dust in grinding or stone-breaking industries is', 'silicosis', ['emphysema', 'asthma', 'bronchitis due to virus'], 'Silicosis comes from silica dust, and asbestosis from asbestos. Workers should wear protective masks.');
mc(3, 'respiratory organs', 'Which animal shows both gills and lungs in its life cycle?', 'Frog', ['Goat', 'Cockroach', 'Earthworm'], 'The tadpole breathes through gills; the adult frog uses lungs and skin.');
mc(3, 'mechanism of breathing', 'The diaphragm contracts and flattens during inspiration. This', 'increases the antero-posterior axis of the thoracic cavity', ['decreases the volume of the thorax', 'increases pressure inside the lungs', 'relaxes the intercostal muscles'], 'Contraction of the diaphragm increases the volume in the antero-posterior axis. The lung pressure becomes lower than the atmospheric pressure and air rushes in.');
mc(3, 'mechanism of breathing', 'The additional muscles that help in forceful inspiration and expiration are those of the', 'abdomen', ['hands', 'neck only', 'thigh'], 'The additional abdominal muscles can increase the strength of inspiration and expiration.');
mc(3, 'transport of gases', 'Which of the following is correct for the transport of O<sub>2</sub>?', 'Nearly 97% is carried by RBC as oxyhaemoglobin', ['Nearly 97% is carried in the plasma', 'It is carried only as bicarbonate', 'It is carried as carbamino compounds'], 'RBCs carry around 97%; plasma only about 3% dissolved.');
mc(3, 'transport of gases', 'A person has 5 L of oxygenated blood circulating through tissues in a minute. If each 100 mL delivers 5 mL of oxygen, the oxygen given to tissues each minute is', '250 mL', ['25 mL', '500 mL', '2500 mL'], '5000 mL / 100 mL = 50 units; 50 × 5 mL = 250 mL.', 'Using 5 L as 5 mL.');
mc(3, 'transport of gases', 'In RBCs the reaction CO<sub>2</sub> + H<sub>2</sub>O &rarr; H<sub>2</sub>CO<sub>3</sub> is very fast because the cells have', 'high concentration of carbonic anhydrase', ['high concentration of catalase', 'a nucleus with DNA', 'many mitochondria'], 'Carbonic anhydrase is present in very high concentration in RBCs and in smaller amounts in plasma.');
mc(3, 'human respiratory system', 'Which of the following parts is NOT lined by incomplete cartilaginous rings?', 'Alveolar duct', ['Trachea', 'Secondary bronchus', 'Tertiary bronchus'], 'Cartilage support continues up to the initial bronchioles. Alveolar ducts and alveoli are thin-walled with no cartilage.');
mc(3, 'respiratory volumes', 'A person breathes 14 times a minute with a tidal volume of 450 mL. The air moved per minute is', '6300 mL', ['5400 mL', '6000 mL', '7200 mL'], '14 × 450 = 6300 mL per minute.');
mc(3, 'respiratory volumes', 'Which statement about vital capacity is correct?', 'It is larger than the inspiratory capacity of the same person', ['It is smaller than the tidal volume', 'It includes residual volume', 'It equals total lung capacity'], 'VC = IC + ERV, so it is greater than IC. TLC = VC + RV.');
mc(3, 'exchange of gases', 'Which of the following helps in the rapid exchange of gases across the alveolar membrane?', 'The thin membrane of less than a millimetre in thickness and large surface area', ['A thick basement substance', 'Absence of capillaries', 'Low solubility of gases'], 'A thin, large, well-vascularised surface makes diffusion fast.');

// ---------------------------------------------------------------- Level 4
mc(4, 'transport of gases', 'Which set of changes in a tissue will shift the oxygen dissociation curve to the right?', 'Increase in pCO<sub>2</sub>, decrease in pH and increase in temperature', ['Decrease in pCO<sub>2</sub>, increase in pH and decrease in temperature', 'Increase in pO<sub>2</sub> only', 'Decrease in pCO<sub>2</sub> and increase in temperature'], 'A right shift (lower affinity) occurs with more CO<sub>2</sub>, more H<sup>+</sup> (lower pH) and higher temperature. The reverse set is for a left shift.', 'Higher H<sup>+</sup> means lower pH.');
mc(4, 'transport of gases', 'At the same low pO<sub>2</sub>, the percentage saturation of haemoglobin will be least in', 'a tissue with high pCO<sub>2</sub> and low pH', ['the alveoli', 'a cool region of the body', 'a tissue with low pCO<sub>2</sub>'], 'The curve is shifted right in acidic, CO<sub>2</sub>-rich, warm tissue, so at a given pO<sub>2</sub> less O<sub>2</sub> stays on Hb.');
mc(4, 'transport of gases', 'Which statement about carbamino-haemoglobin is correct?', 'CO<sub>2</sub> binds to the globin part, and about 20 to 25 per cent of CO<sub>2</sub> is carried this way', ['CO<sub>2</sub> binds to the iron of haem', 'About 70 per cent of CO<sub>2</sub> is carried this way', 'It forms mainly in the plasma'], 'CO<sub>2</sub> binds to amino groups in globin, not to the haem iron where O<sub>2</sub> binds. The amount bound depends on pCO<sub>2</sub> and on the amount of oxyhaemoglobin.');
mc(4, 'transport of gases', 'In the tissues the binding of CO<sub>2</sub> with haemoglobin is favoured when', 'pCO<sub>2</sub> is high and pO<sub>2</sub> is low', ['pCO<sub>2</sub> is low and pO<sub>2</sub> is high', 'both are high', 'both are low'], 'Binding is favoured at high pCO<sub>2</sub> and low pO<sub>2</sub> in the tissues. In the alveoli pCO<sub>2</sub> is low and pO<sub>2</sub> is high, so CO<sub>2</sub> is released.');
mc(4, 'exchange of gases', 'Which of the following is true about the movement of gases at the tissue level?', 'O<sub>2</sub> diffuses from blood (95 mm Hg) to tissue (40 mm Hg), and CO<sub>2</sub> from tissue (45 mm Hg) to blood (40 mm Hg)', ['O<sub>2</sub> diffuses from tissue to blood', 'CO<sub>2</sub> moves from blood (40) to tissue (45)', 'Both gases move by active transport'], 'Diffusion follows the partial pressure gradient from higher to lower pressure. Both gases move passively.');
mc(4, 'exchange of gases', 'The factors that affect the rate of diffusion of gases through the alveolar membrane include', 'pressure gradient, solubility of the gas and thickness of the membrane', ['only pressure gradient', 'only the thickness of the membrane', 'the colour of the blood'], 'The factors are the partial pressure gradient, the solubility of the gases and the thickness of the diffusion membrane.');
mc(4, 'mechanism of breathing', 'During a forced expiration which of these happens?', 'Abdominal muscles contract and push the diaphragm up', ['The diaphragm contracts and flattens', 'The external intercostal muscles contract', 'Intra-pulmonary pressure falls below the atmospheric pressure'], 'A forced expiration needs the abdominal muscles to push the relaxed diaphragm upward, which increases the pressure in the lungs.', 'Normal expiration is passive; forced is active.');
mc(4, 'mechanism of breathing', 'Which sequence is correct for inspiration?', 'Diaphragm and external intercostals contract, thoracic volume rises, lung pressure falls, air enters', ['Lung pressure falls, thoracic volume rises, muscles contract, air enters', 'Thoracic volume falls, lung pressure rises, air enters', 'Diaphragm relaxes, lung pressure falls, air enters'], 'Muscle contraction is the cause. The volume rise lowers the pressure, and the pressure gradient moves the air.');
mc(4, 'respiratory volumes', 'A person breathes out 4800 mL after a deep breath and has RV of 1200 mL. If ERV is 1100 mL and TV is 500 mL, her IRV is', '3200 mL', ['2400 mL', '3100 mL', '3700 mL'], 'VC = 4800. IRV = VC - TV - ERV = 4800 - 500 - 1100 = 3200 mL. RV is not part of VC.', 'Adding RV by mistake.');
mc(4, 'respiratory volumes', 'The decrease in vital capacity is commonly seen in', 'diseases that damage lung tissue or weaken the respiratory muscles', ['athletes after training', 'people who live at sea level', 'people with deep breathing'], 'Fibrosis (silicosis), emphysema or muscle weakness lower the vital capacity. This is why spirometry is used clinically.');
mc(4, 'respiratory volumes', 'Which pair of volumes together adds up to the expiratory capacity?', 'Tidal volume and expiratory reserve volume', ['Tidal volume and inspiratory reserve volume', 'Residual volume and expiratory reserve volume', 'Inspiratory reserve volume and expiratory reserve volume'], 'EC = TV + ERV. The other pairs: TV + IRV = IC, RV + ERV = FRC.');
mc(4, 'regulation of respiration', 'Which of these correctly explains why holding the breath for long makes the urge to breathe stronger?', 'CO<sub>2</sub> and H<sup>+</sup> build up and activate the chemosensitive area', ['O<sub>2</sub> falls and directly stimulates the rhythm centre', 'The pneumotaxic centre stops working', 'The diaphragm loses its nerve supply'], 'Rising CO<sub>2</sub> and H<sup>+</sup> stimulate the chemosensitive area, which signals the rhythm centre to restart breathing. NCERT calls the role of O<sub>2</sub> insignificant.', 'Many students pick low O2 as the cause.');
mc(4, 'regulation of respiration', 'If the chemosensitive area is stimulated by an increase in H<sup>+</sup>, the rhythm centre will', 'increase the depth and rate of breathing so more CO<sub>2</sub> is removed', ['decrease the rate of breathing', 'stop breathing', 'only increase the heart rate'], 'Increased CO<sub>2</sub> and H<sup>+</sup> activate the rhythm centre, which makes a stronger respiratory effort that removes CO<sub>2</sub>.');
mc(4, 'disorders', 'Which of the following is NOT correct for asthma?', 'It is caused by alveolar damage due to smoking', ['It is an inflammation of the bronchi and bronchioles', 'It causes wheezing', 'It makes breathing difficult'], 'Alveolar damage from smoking is emphysema. Asthma is inflammation of the bronchi and bronchioles.');
mc(4, 'disorders', 'Smoking increases the risk of emphysema because', 'it damages the alveolar walls and reduces the surface for gas exchange', ['it increases the thickness of the diaphragm', 'it adds more alveoli', 'it removes the pleura'], 'Cigarette smoke is the major cause of emphysema, by breaking down alveolar walls.');
mc(4, 'human respiratory system', 'Which sequence of air passage is correct?', 'Nasal chamber, nasopharynx, larynx, trachea, bronchi, bronchioles, alveoli', ['Nasal chamber, larynx, nasopharynx, trachea, bronchi', 'Nasopharynx, nasal chamber, trachea, larynx', 'Trachea, larynx, bronchi, nasopharynx'], 'Air moves from nose through nasal chamber and nasopharynx to the larynx through the glottis, then the trachea, bronchi and bronchioles to the alveoli.');
mc(4, 'human respiratory system', 'The glottis is', 'the opening into the larynx, which can be covered by the epiglottis', ['the cartilage of the larynx', 'the opening of the oesophagus', 'a bronchus'], 'Food is prevented from entering the larynx by the epiglottis, a thin elastic cartilaginous flap, during swallowing.');
mc(4, 'respiratory organs', 'Which pair is NOT correctly matched?', 'Bird : gills', ['Cockroach : tracheal tubes', 'Earthworm : moist cuticle', 'Prawn : gills'], 'Birds breathe with lungs. The other three pairs are correct.');
mc(4, 'respiratory organs', 'Which of these animals exchanges gases without any special respiratory organ?', 'Planaria', ['Locust', 'Shark', 'Pigeon'], 'Flatworms like Planaria respire by diffusion across the body surface. Locust has tracheae, shark gills, pigeon lungs.');
mc(4, 'exchange of gases', 'Which of the following has the highest partial pressure of CO<sub>2</sub>?', 'Tissues and deoxygenated blood (45 mm Hg)', ['Alveolar air', 'Oxygenated blood', 'Atmospheric air'], 'Tissues and deoxygenated blood have pCO<sub>2</sub> of 45 mm Hg. Alveoli and oxygenated blood have 40, and atmospheric air 0.3.');
mc(4, 'transport of gases', 'Which of the following correctly shows the transport of CO<sub>2</sub> (in the order of percentage, high to low)?', 'Bicarbonate, carbamino-haemoglobin, dissolved in plasma', ['Dissolved in plasma, bicarbonate, carbamino-haemoglobin', 'Carbamino-haemoglobin, bicarbonate, dissolved', 'Bicarbonate, dissolved, carbamino-haemoglobin'], 'About 70%, 20-25% and 7% respectively.');
mc(4, 'respiratory volumes', 'The functional residual capacity in a person is 2300 mL and the expiratory reserve volume is 1100 mL. The residual volume is', '1200 mL', ['1100 mL', '2300 mL', '3400 mL'], 'FRC = ERV + RV, so RV = 2300 - 1100 = 1200 mL.');
mc(4, 'mechanism of breathing', 'Which of these is a correct comparison of quiet inspiration and quiet expiration?', 'Inspiration is active and expiration is largely passive', ['Both are active', 'Both are passive', 'Inspiration is passive and expiration is active'], 'Inspiration needs muscle contraction; expiration is from relaxation, so it is passive.');

// ---------------------------------------------------------------- Level 5
mc(5, 'transport of gases', 'A person moves from rest to heavy exercise. Which of the following changes does NOT help to deliver more oxygen to the muscles?', 'A left shift of the oxygen dissociation curve', ['A rise in muscle temperature', 'An increase in pCO<sub>2</sub> in the muscle', 'A fall in pH in the muscle'], 'A left shift increases the affinity of Hb for O<sub>2</sub>, so less O<sub>2</sub> is released. The other three cause a right shift (Bohr effect).', 'A right shift is helpful for unloading.');
mc(5, 'transport of gases', 'Which of the following is correct about the oxygen dissociation curve?', 'At low pO<sub>2</sub> the curve is steep, so a small fall in pO<sub>2</sub> unloads a lot of O<sub>2</sub>', ['It is a straight line from zero', 'At very high pO<sub>2</sub> it falls to zero', 'It is steepest at 104 mm Hg'], 'In the sigmoid curve the steep part lies at the lower pO<sub>2</sub> range, which is why tissues receive plenty of O<sub>2</sub> for a small fall in pressure. Near the alveolar values it is almost flat.');
mc(5, 'exchange of gases', 'Which of the following correctly lists pO<sub>2</sub> (mm Hg) in atmospheric air, alveoli, deoxygenated blood and oxygenated blood?', '159, 104, 40, 95', ['104, 159, 95, 40', '159, 104, 95, 40', '40, 104, 159, 95'], 'Atmospheric 159, alveolar 104, deoxygenated 40, oxygenated 95. The CO<sub>2</sub> list is 0.3, 40, 45, 40.', 'Oxygenated blood 95 is below alveolar 104.');
mc(5, 'exchange of gases', 'Which of the following correctly lists pCO<sub>2</sub> (mm Hg) in atmospheric air, alveoli, deoxygenated blood and oxygenated blood?', '0.3, 40, 45, 40', ['0.3, 45, 40, 40', '40, 0.3, 45, 45', '0.3, 40, 40, 45'], 'Atmosphere 0.3, alveoli 40, deoxygenated blood 45, oxygenated blood 40 mm Hg.');
mc(5, 'respiratory volumes', 'A subject has IC = 3500 mL, FRC = 2300 mL and ERV = 1100 mL. The total lung capacity is', '5800 mL', ['4600 mL', '5400 mL', '6900 mL'], 'TLC = IC + FRC = 3500 + 2300 = 5800 mL. (IC = TV + IRV and FRC = ERV + RV, so IC + FRC adds all four volumes.)', 'Using ERV is not needed.');
mc(5, 'respiratory volumes', 'Given: VC = 4000 mL, TLC = 5200 mL, EC = 1600 mL, IC = 2900 mL. The tidal volume is', '500 mL', ['600 mL', '1100 mL', '1300 mL'], 'VC = IC + ERV, so ERV = 4000 - 2900 = 1100. EC = TV + ERV, so TV = 1600 - 1100 = 500 mL.', 'Needs two relations together.');
mc(5, 'mechanism of breathing', 'A puncture in the chest wall that lets air into the pleural cavity causes the lung to collapse. The reason is that', 'the pressure in the pleural cavity becomes equal to the atmosphere and the lung no longer follows the thorax', ['the diaphragm stops contracting', 'the alveoli fill with blood', 'carbonic anhydrase fails'], 'The lung is held out by the air-tight thoracic cavity and pleural fluid. An opening destroys the air-tight condition, so the lung recoils.');
mc(5, 'regulation of respiration', 'A person breathes into a closed bag and re-breathes the same air. Which change comes first and drives the rate to go up?', 'Rise of CO<sub>2</sub> and H<sup>+</sup> sensed by the chemosensitive area', ['Fall of O<sub>2</sub> sensed by the rhythm centre', 'Fall of temperature', 'Rise of pO<sub>2</sub>'], 'CO<sub>2</sub> builds up and H<sup>+</sup> rises long before O<sub>2</sub> falls much. The chemosensitive area near the rhythm centre responds to these.', 'Choosing O2 as the main driver.');
mc(5, 'disorders', 'Which disorder is mainly a loss of respiratory surface, with the alveolar walls damaged?', 'Emphysema', ['Asthma', 'Common cold', 'Bronchial inflammation in hay fever only'], 'In emphysema alveolar walls are damaged, so the surface for exchange is reduced. Asthma is inflammation of the bronchi and bronchioles, with the alveoli intact.', 'Asthma is about the airways, emphysema about the alveoli.');
mc(5, 'transport of gases', 'How many of these statements are correct? (i) Haemoglobin has a higher affinity for O<sub>2</sub> in the alveoli. (ii) RBCs contain carbonic anhydrase. (iii) About 70 per cent of O<sub>2</sub> is dissolved in plasma. (iv) CO<sub>2</sub> binds to the haem iron.', 'Two', ['One', 'Three', 'Four'], '(i) true, (ii) true, (iii) false: about 3% O<sub>2</sub> is dissolved, and 70% refers to CO<sub>2</sub> as bicarbonate, (iv) false: CO<sub>2</sub> binds to globin amino groups. So two are correct.', 'Mixing percentages of O2 and CO2.', 'statements');
mc(5, 'mixed', 'In heavy exercise the cardiac output increases from 5 L to 20 L per minute. If each 100 mL of blood still delivers 5 mL of oxygen, the oxygen delivered per minute rises by', '750 mL', ['250 mL', '1000 mL', '1250 mL'], 'O<sub>2</sub> delivered = cardiac output × 5/100. Rest: 5000 × 0.05 = 250 mL. Exercise: 20000 × 0.05 = 1000 mL. The rise is 1000 - 250 = 750 mL.', 'Giving the total instead of the rise.');
mc(5, 'mixed', 'Which of these combinations correctly links the stage of cellular respiration with the gas exchange in lungs?', 'O<sub>2</sub> reaches the mitochondria as the final electron acceptor, and CO<sub>2</sub> from the Krebs cycle leaves through the lungs', ['O<sub>2</sub> is needed in glycolysis for the Krebs cycle', 'CO<sub>2</sub> is produced only in the lungs', 'O<sub>2</sub> reaches cells as bicarbonate'], 'Breathing supplies O<sub>2</sub> for the terminal oxidation in mitochondria. CO<sub>2</sub> comes from the link reaction and the Krebs cycle.', 'Link with the respiration chapter.');

// ---------------------------------------------------------------- Assertion-Reason
asr(2, 'respiratory organs', 'Insects do not need blood to carry oxygen to tissues.', 'The tracheal tubes of insects open directly into the tissues.', 0, 'Insects have air tubes that reach the cells, so oxygen goes directly. R explains A.');
asr(2, 'mechanism of breathing', 'Normal expiration is a passive process.', 'The diaphragm and the external intercostal muscles relax during expiration.', 0, 'Relaxation returns the thorax to its original size without muscle effort, which raises the lung pressure above atmospheric. R explains A.');
asr(3, 'exchange of gases', 'CO<sub>2</sub> diffuses across the alveolar membrane despite a pressure gradient of only about 5 mm Hg.', 'The solubility of CO<sub>2</sub> is 20 to 25 times higher than that of O<sub>2</sub>.', 0, 'The gradient is 45 - 40 = 5 mm Hg, much smaller than the 64 mm Hg for O<sub>2</sub>. The higher solubility lets the same amount cross, so R explains A.');
asr(3, 'transport of gases', 'The oxygen dissociation curve of haemoglobin shifts to the right in active muscles.', 'Active muscles have lower pCO<sub>2</sub> and lower temperature.', 2, 'A is true: more O<sub>2</sub> is released. R is false: active muscles have higher pCO<sub>2</sub> and higher temperature.', 'The shift direction is mixed up with its cause.');
asr(3, 'transport of gases', 'Most of the CO<sub>2</sub> is transported as bicarbonate.', 'RBCs contain a high concentration of carbonic anhydrase.', 0, 'The enzyme quickly forms H<sub>2</sub>CO<sub>3</sub>, which splits into HCO<sub>3</sub><sup>-</sup> and H<sup>+</sup>, so about 70% travels as bicarbonate. R explains A.');
asr(3, 'respiratory volumes', 'The vital capacity is always less than the total lung capacity.', 'The residual volume cannot be expelled from the lungs and is included in the total lung capacity.', 0, 'TLC = VC + RV. Since RV is always positive, VC < TLC. R explains A.');
asr(4, 'regulation of respiration', 'The role of oxygen in the regulation of the respiratory rhythm is quite insignificant.', 'The chemosensitive area of the medulla is highly sensitive to CO<sub>2</sub> and hydrogen ions.', 1, 'Both are true. R is a fact about what does regulate breathing, but it does not directly explain why O<sub>2</sub> is unimportant, so it is not the correct explanation.', 'R is true but does not explain A.');
asr(4, 'disorders', 'Emphysema reduces the surface area available for gas exchange.', 'In emphysema the bronchi and bronchioles are inflamed, producing wheezing.', 2, 'A is true: alveolar walls are damaged. R describes asthma, not emphysema, so R is false for this disease.', 'Asthma and emphysema are confused.');
asr(3, 'respiratory organs', 'The skin of a frog can take part in gas exchange.', 'The skin of a frog is thick, dry and covered with scales.', 2, 'The moist, thin skin of amphibians allows cutaneous respiration. R is false: it is the reptiles that have dry scaly skin.');
asr(5, 'transport of gases', 'Haemoglobin picks up oxygen in the lungs and gives it away in the tissues.', 'The binding of oxygen to haemoglobin depends mainly on pO<sub>2</sub>, and on pCO<sub>2</sub>, H<sup>+</sup> and temperature.', 0, 'High pO<sub>2</sub> and low pCO<sub>2</sub>, H<sup>+</sup> and temperature in alveoli favour loading; the opposite in tissues favours unloading. R explains A.');
asr(5, 'respiratory volumes', 'Residual volume cannot be measured with a simple spirometer.', 'The residual volume is the air that is left in the lungs after a forced expiration.', 0, 'The spirometer records only air that moves in and out. RV never leaves the lungs, so it is not recorded. R explains A.');

// ---------------------------------------------------------------- Statements
stm(2, 'human respiratory system', 'The conducting part of the human respiratory system extends from the external nostrils to the terminal bronchioles.', 'Alveoli are part of the exchange part of the system.', 0, 'Both are correct. The conducting part carries and conditions the air. The alveoli exchange the gases.');
stm(2, 'respiratory organs', 'Earthworms exchange gases through their moist cuticle.', 'Insects exchange gases through gills.', 2, 'I is correct. II is wrong: insects use a network of tracheal tubes.');
stm(3, 'respiratory volumes', 'Vital capacity is the sum of TV, IRV and ERV.', 'Functional residual capacity is the sum of IRV and RV.', 2, 'I is correct. FRC = ERV + RV, so II is wrong.', 'FRC takes ERV, not IRV.');
stm(3, 'transport of gases', 'About 97 per cent of oxygen is transported by RBCs.', 'About 97 per cent of CO<sub>2</sub> is transported by RBCs as bicarbonate.', 2, 'I is true. About 70% of CO<sub>2</sub> is carried as bicarbonate and 20-25% as carbamino-haemoglobin, so II is wrong.');
stm(3, 'exchange of gases', 'The partial pressure of oxygen in the alveolar air is lower than that in atmospheric air.', 'The partial pressure of CO<sub>2</sub> in the alveoli is lower than that in tissues.', 0, 'Alveolar pO<sub>2</sub> is 104 against 159 in the atmosphere. Alveolar pCO<sub>2</sub> is 40 against 45 in tissues. Both are correct.');
stm(3, 'mechanism of breathing', 'Air enters the lungs when the intra-pulmonary pressure is higher than the atmospheric pressure.', 'The diaphragm contracts during inspiration.', 3, 'I is wrong: air enters when the pressure in the lungs is lower than outside. II is correct.');
stm(4, 'regulation of respiration', 'The respiratory rhythm centre is in the pons.', 'The pneumotaxic centre is in the medulla oblongata.', 1, 'Both are wrong, and the places are swapped: the rhythm centre is in the medulla and the pneumotaxic centre in the pons.', 'The two names are swapped.');
stm(4, 'disorders', 'Silicosis is an occupational disease caused by exposure to silica dust.', 'Emphysema is chiefly caused by long exposure to dust in stone-breaking industries.', 2, 'I is correct. II is wrong: the major cause of emphysema is cigarette smoking; dust in stone-breaking industries causes fibrosis such as silicosis.');
stm(4, 'transport of gases', 'In the tissues the oxygen dissociation curve of Hb moves to the right.', 'This movement means that the affinity of haemoglobin for oxygen is higher in the tissues.', 2, 'I is correct. A right shift means lower affinity, so II is wrong.', 'Right shift is lower affinity.');
stm(5, 'exchange of gases', 'Oxygenated blood leaving the lungs has pO<sub>2</sub> of 95 mm Hg and pCO<sub>2</sub> of 40 mm Hg.', 'Deoxygenated blood reaching the lungs has pO<sub>2</sub> of 40 mm Hg and pCO<sub>2</sub> of 45 mm Hg.', 0, 'Both match the table of partial pressures in NCERT.');
mc(4, 'mixed', 'Consider these statements. (a) The thoracic cavity is air-tight. (b) Lungs are muscular and expand on their own. (c) The diaphragm contracts in inspiration. (d) The external intercostals lift the ribs. How many are correct?', 'Three', ['Two', 'Four', 'One'], '(a), (c) and (d) are correct. (b) is wrong because the lungs have no muscle; they follow the thorax.', 'The lungs do not expand by themselves.', 'statements');
mc(5, 'mixed', 'How many of the following are included in the conducting part of the respiratory system: nasal chamber, larynx, trachea, tertiary bronchus, terminal bronchiole, alveolar sac?', 'Five', ['Four', 'Six', 'Three'], 'The conducting part goes from the nostrils up to the terminal bronchioles. So the first five are in it. Alveolar sac belongs to the exchange region.', 'Alveoli are not conducting.', 'statements');

// ---------------------------------------------------------------- Matching
match(2, 'respiratory volumes', 'm1', 'Capacities and their volumes',
  ['A. Vital capacity', 'B. Functional residual capacity', 'C. Inspiratory capacity', 'D. Total lung capacity'],
  ['p. ERV + RV', 'q. TV + IRV', 'r. ERV + TV + IRV', 's. VC + RV'],
  'A-r, B-p, C-q, D-s', ['A-p, B-r, C-q, D-s', 'A-r, B-q, C-p, D-s', 'A-s, B-p, C-q, D-r'],
  'VC = ERV + TV + IRV (r). FRC = ERV + RV (p). IC = TV + IRV (q). TLC = VC + RV (s).');
match(3, 'respiratory organs', 'm2', 'Animals and their respiratory structures',
  ['A. Earthworm', 'B. Cockroach', 'C. Bony fish', 'D. Sponge'],
  ['p. Tracheal tubes', 'q. Moist cuticle', 'r. Gills', 's. Diffusion over the body surface'],
  'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'],
  'Earthworm: moist cuticle (q). Cockroach: tracheal tubes (p). Fish: gills (r). Sponge: body surface (s).');
match(3, 'exchange of gases', 'm3', 'Partial pressures in mm Hg',
  ['A. pO<sub>2</sub> in atmospheric air', 'B. pO<sub>2</sub> in alveolar air', 'C. pCO<sub>2</sub> in deoxygenated blood', 'D. pCO<sub>2</sub> in alveolar air'],
  ['p. 40', 'q. 45', 'r. 104', 's. 159'],
  'A-s, B-r, C-q, D-p', ['A-r, B-s, C-q, D-p', 'A-s, B-r, C-p, D-q', 'A-s, B-q, C-r, D-p'],
  'Atmospheric pO<sub>2</sub> 159 (s), alveolar pO<sub>2</sub> 104 (r), deoxygenated blood pCO<sub>2</sub> 45 (q), alveolar pCO<sub>2</sub> 40 (p).');
match(4, 'disorders', 'm4', 'Respiratory disorders',
  ['A. Asthma', 'B. Emphysema', 'C. Silicosis', 'D. Asbestosis'],
  ['p. Alveolar walls damaged, surface reduced', 'q. Wheezing from inflamed bronchi and bronchioles', 'r. Fibrosis from silica dust', 's. Fibrosis from asbestos fibres'],
  'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'],
  'Asthma (q), emphysema (p), silicosis (r), asbestosis (s).', 'Silicosis and asbestosis look alike; know the dust.');
match(4, 'regulation of respiration', 'm5', 'Regulation of breathing',
  ['A. Respiratory rhythm centre', 'B. Pneumotaxic centre', 'C. Chemosensitive area', 'D. Peripheral chemoreceptors'],
  ['p. Pons', 'q. Medulla', 'r. Adjacent to the rhythm centre, sensitive to CO<sub>2</sub> and H<sup>+</sup>', 's. Aortic arch and carotid artery'],
  'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'],
  'Rhythm centre: medulla (q). Pneumotaxic: pons (p). Chemosensitive area: near the rhythm centre (r). Receptors: aortic arch and carotid (s).');

// ---------------------------------------------------------------- Passages
pass('p1', 'A spirometer record', 'A student\'s spirometer test gave these values. Tidal volume 500 mL, expiratory reserve volume 1100 mL, vital capacity 4000 mL. The residual volume of the student was known to be 1200 mL.');
pq('p1', 3, 'respiratory volumes', 'The inspiratory reserve volume of the student is', '2400 mL', ['2900 mL', '3500 mL', '1900 mL'], 'IRV = VC - TV - ERV = 4000 - 500 - 1100 = 2400 mL.');
pq('p1', 3, 'respiratory volumes', 'The total lung capacity of the student is', '5200 mL', ['4000 mL', '5800 mL', '6300 mL'], 'TLC = VC + RV = 4000 + 1200 = 5200 mL.');
pq('p1', 4, 'respiratory volumes', 'The functional residual capacity and inspiratory capacity are respectively', '2300 mL and 2900 mL', ['2300 mL and 2400 mL', '1600 mL and 2900 mL', '2900 mL and 2300 mL'], 'FRC = ERV + RV = 1100 + 1200 = 2300 mL. IC = TV + IRV = 500 + 2400 = 2900 mL. Their sum is 5200 mL, equal to TLC, a good check.');
pass('p2', 'Haemoglobin and oxygen', 'A sprinter\'s leg muscles are working hard. Their temperature is higher, pCO<sub>2</sub> is high and the pH is lower than in resting tissue. The sprinter\'s blood passes through these muscles and then through the lungs.');
pq('p2', 3, 'transport of gases', 'In the working muscle the oxygen dissociation curve will', 'shift to the right', ['shift to the left', 'remain the same', 'become a straight line'], 'Higher temperature, higher pCO<sub>2</sub> and lower pH all lower the affinity of Hb for O<sub>2</sub>. This is the Bohr effect.');
pq('p2', 4, 'transport of gases', 'The advantage of this shift for the sprinter is that', 'haemoglobin gives up more O<sub>2</sub> at the same pO<sub>2</sub> in the muscle', ['haemoglobin holds more O<sub>2</sub> at the same pO<sub>2</sub>', 'more CO<sub>2</sub> stays in the muscle', 'the muscle does not need O<sub>2</sub>'], 'Lower affinity means more O<sub>2</sub> is released where it is needed most.');
pq('p2', 4, 'transport of gases', 'When the blood reaches the alveoli, which change helps reload haemoglobin with oxygen?', 'Lower pCO<sub>2</sub>, lower H<sup>+</sup> and higher pO<sub>2</sub>', ['Higher pCO<sub>2</sub> and higher temperature', 'Lower pO<sub>2</sub> and lower pH', 'More carbamino-haemoglobin'], 'The alveolar conditions are the opposite of those in the muscle, so the curve moves left and Hb gains O<sub>2</sub>.');
pass('p3', 'Partial pressures', 'The table (mm Hg) lists pO<sub>2</sub> and pCO<sub>2</sub>. Alveoli: 104 and 40. Deoxygenated blood: 40 and 45. Oxygenated blood: 95 and 40. Tissues: 40 and 45.');
pq('p3', 3, 'exchange of gases', 'The O<sub>2</sub> pressure difference that drives oxygen from the alveoli into the deoxygenated blood is', '64 mm Hg', ['5 mm Hg', '55 mm Hg', '104 mm Hg'], '104 - 40 = 64 mm Hg.');
pq('p3', 4, 'exchange of gases', 'The CO<sub>2</sub> pressure difference that drives CO<sub>2</sub> from the blood into the alveoli is only', '5 mm Hg', ['40 mm Hg', '64 mm Hg', '45 mm Hg'], '45 - 40 = 5 mm Hg. It is enough because CO<sub>2</sub> is 20 to 25 times more soluble than O<sub>2</sub>.');
pq('p3', 4, 'exchange of gases', 'Between the oxygenated blood and the tissue, the net movement of the gases will be', 'O<sub>2</sub> to the tissue and CO<sub>2</sub> to the blood', ['O<sub>2</sub> to the blood and CO<sub>2</sub> to the tissue', 'O<sub>2</sub> and CO<sub>2</sub> both to the tissue', 'no net movement'], 'O<sub>2</sub> moves from 95 to 40 (blood to tissue) and CO<sub>2</sub> from 45 to 40 (tissue to blood).');

// ---------------------------------------------------------------- Number templates
const gens = [];
const gm = (id, level, sub, make, verify) => gens.push({ id, type: 'nat', level, exams: E, sub, make, verify });
gm('br-g01', 3, 'respiratory volumes', (rng) => {
  const tv = pick(rng, 400, 600, 50), irv = pick(rng, 2400, 3200, 100), erv = pick(rng, 900, 1200, 100);
  const a = tv + irv + erv;
  return { q: `A person has a tidal volume of ${tv} mL, an inspiratory reserve volume of ${irv} mL and an expiratory reserve volume of ${erv} mL. What is the vital capacity in mL?`, answer: a, tol: 0, unit: 'mL', tv, irv, erv, sol: `Vital capacity = TV + IRV + ERV = ${tv} + ${irv} + ${erv} = ${a} mL.` };
}, (p) => p.tv + p.irv + p.erv);
gm('br-g02', 3, 'respiratory volumes', (rng) => {
  const vc = pick(rng, 3800, 4800, 100), rv = pick(rng, 1100, 1200, 50);
  const a = vc + rv;
  return { q: `The vital capacity of a student is ${vc} mL and the residual volume is ${rv} mL. Find the total lung capacity in mL.`, answer: a, tol: 0, unit: 'mL', vc, rv, sol: `Total lung capacity = vital capacity + residual volume = ${vc} + ${rv} = ${a} mL.` };
}, (p) => p.vc + p.rv);
gm('br-g03', 4, 'respiratory volumes', (rng) => {
  const tv = pick(rng, 450, 550, 50), ic = pick(rng, 2900, 3600, 100);
  const a = ic - tv;
  return { q: `The inspiratory capacity of a person is ${ic} mL and the tidal volume is ${tv} mL. Find the inspiratory reserve volume in mL.`, answer: a, tol: 0, unit: 'mL', tv, ic, sol: `IC = TV + IRV, so IRV = IC - TV = ${ic} - ${tv} = ${a} mL.` };
}, (p) => p.ic - p.tv);
gm('br-g04', 3, 'respiratory volumes', (rng) => {
  const tv = pick(rng, 400, 600, 50), r = pick(rng, 12, 18, 1);
  const a = tv * r;
  return { q: `A person breathes ${r} times a minute with a tidal volume of ${tv} mL. How many mL of air move in and out of the lungs in one minute?`, answer: a, tol: 0, unit: 'mL', tv, r, sol: `Volume per minute = tidal volume × breaths per minute = ${tv} × ${r} = ${a} mL.` };
}, (p) => p.r * p.tv);
gm('br-g05', 4, 'respiratory volumes', (rng) => {
  const erv = pick(rng, 1000, 1200, 50), rv = pick(rng, 1100, 1200, 50);
  const a = erv + rv;
  return { q: `A person has an expiratory reserve volume of ${erv} mL and a residual volume of ${rv} mL. What is the functional residual capacity in mL?`, answer: a, tol: 0, unit: 'mL', erv, rv, sol: `FRC = ERV + RV = ${erv} + ${rv} = ${a} mL. This is the air left in the lungs after a normal expiration.` };
}, (p) => p.erv + p.rv);
gm('br-g06', 3, 'transport of gases', (rng) => {
  const v = pick(rng, 2000, 6000, 500);
  const a = v * 5 / 100;
  return { q: `Each 100 mL of oxygenated blood gives about 5 mL of oxygen to the tissues. How many mL of oxygen are given to the tissues by ${v} mL of blood?`, answer: a, tol: 0, unit: 'mL', v, sol: `Number of 100 mL parts = ${v}/100 = ${v / 100}. Oxygen = ${v / 100} × 5 = ${a} mL.` };
}, (p) => (p.v / 100) * 5);
gm('br-g07', 4, 'respiratory volumes', (rng) => {
  const tv = pick(rng, 450, 550, 50), erv = pick(rng, 1000, 1200, 50), rv = pick(rng, 1100, 1200, 50), irv = pick(rng, 2400, 3200, 100);
  const a = tv + irv + erv + rv;
  return { q: `The four lung volumes of a student are TV = ${tv} mL, IRV = ${irv} mL, ERV = ${erv} mL and RV = ${rv} mL. What is her total lung capacity in mL?`, answer: a, tol: 0, unit: 'mL', tv, irv, erv, rv, sol: `TLC is the sum of all four volumes: ${tv} + ${irv} + ${erv} + ${rv} = ${a} mL.` };
}, (p) => (p.tv + p.irv) + (p.erv + p.rv));
gm('br-g08', 3, 'exchange of gases', (rng) => {
  const alv = choose(rng, [104, 104, 100]), tis = choose(rng, [40, 40, 38]);
  const a = alv - tis;
  return { q: `The partial pressure of oxygen is ${alv} mm Hg in the alveoli and ${tis} mm Hg in the blood that arrives at the lungs. What is the pressure difference that drives the diffusion, in mm Hg?`, answer: a, tol: 0, unit: 'mm Hg', alv, tis, sol: `Gases move from higher to lower partial pressure. The driving difference is ${alv} - ${tis} = ${a} mm Hg.` };
}, (p) => p.alv - p.tis);
gm('br-g09', 4, 'respiratory volumes', (rng) => {
  const tv = pick(rng, 450, 550, 50), erv = pick(rng, 1000, 1200, 50), vc = pick(rng, 4000, 4800, 100);
  const a = vc - tv - erv;
  return { q: `A subject has a vital capacity of ${vc} mL, tidal volume of ${tv} mL and expiratory reserve volume of ${erv} mL. What is her inspiratory reserve volume in mL?`, answer: a, tol: 0, unit: 'mL', tv, erv, vc, sol: `VC = TV + IRV + ERV, so IRV = ${vc} - ${tv} - ${erv} = ${a} mL.` };
}, (p) => p.vc - (p.tv + p.erv));
gens.push({ id: 'br-g10', type: 'mcq', level: 3, exams: E, sub: 'respiratory volumes', make: (rng) => {
  const tv = pick(rng, 450, 550, 50), erv = pick(rng, 1000, 1200, 50);
  const correct = tv + erv;
  const r = numOpts(rng, correct, [tv + erv + 1200, tv, erv], 'mL', 4);
  return { q: `A person with TV = ${tv} mL and ERV = ${erv} mL is being tested. What is her expiratory capacity (EC)?`, options: r.options, answer: r.answer, exp: `${correct} mL`, sol: `EC = TV + ERV = ${tv} + ${erv} = ${correct} mL. Adding RV gives FRC-like numbers, which is wrong.` };
}, verify: (p) => p.options.indexOf(p.exp) });

// ===== EXPANSION (round 2) =====
const hm = (level, sub, q, correct, wrongs, sol, trap) => mc(level, sub, q, correct, wrongs, sol, trap, 'statements');
// ---- Level 2
mc(2, 'respiratory organs', 'In sponges, coelenterates and flatworms, the exchange of O2 and CO2 takes place by', 'simple diffusion over the entire body surface', ['gills', 'tracheal tubes', 'lungs'], 'These simple animals have no special respiratory organs. Gases diffuse across the whole body surface.');
mc(2, 'respiratory organs', 'Aquatic arthropods and molluscs breathe by', 'gills (branchial respiration)', ['lungs', 'tracheae', 'cuticle only'], 'Gills are vascularised structures for exchange of gases dissolved in water. Insects use tracheae; terrestrial vertebrates use lungs.');
mc(2, 'respiratory organs', 'Which vertebrates breathe through lungs and also through the moist skin?', 'Amphibians such as frogs', ['Fishes', 'Birds', 'Reptiles'], 'Amphibians use lungs and also cutaneous respiration through their moist skin. Reptiles, birds and mammals use lungs.');
mc(2, 'human respiratory system', 'The nasal chamber opens into the larynx through the', 'pharynx (nasopharynx)', ['trachea directly', 'bronchioles', 'alveoli'], 'Air from the nostrils passes through the nasal chamber, the nasopharynx and the glottis into the larynx.');
mc(2, 'human respiratory system', 'The larynx is called the', 'sound box', ['wind pipe', 'air sac', 'lung bud'], 'The larynx is a cartilaginous box that helps in sound production. The glottis is the opening into it, covered by the epiglottis during swallowing.');
mc(2, 'human respiratory system', 'The trachea is kept open at all times by', 'incomplete cartilaginous rings', ['complete bony rings', 'smooth muscle only', 'the diaphragm'], 'The trachea is a straight tube supported by incomplete rings of cartilage. Its extension divides into right and left primary bronchi.');
mc(2, 'human respiratory system', 'The lungs are covered by a double-layered membrane called the', 'pleura', ['peritoneum', 'pericardium', 'meninges'], 'The pleura has pleural fluid between its two layers, which reduces friction on the lung surface.');
mc(2, 'mechanism of breathing', 'The muscles that take part in normal inspiration are', 'the diaphragm and the external intercostal muscles', ['the internal intercostal muscles only', 'the abdominal muscles only', 'the biceps'], 'Contraction of the diaphragm increases the volume of the thoracic chamber in the antero-posterior axis, and the external intercostals lift the ribs and sternum to increase it in the dorso-ventral axis.');
mc(2, 'transport of gases', 'About what percentage of oxygen is carried dissolved in the plasma?', '3 per cent', ['97 per cent', '20 per cent', '50 per cent'], 'About 97 per cent of oxygen is carried by RBCs as oxyhaemoglobin; the remaining 3 per cent is dissolved in plasma.');
mc(2, 'transport of gases', 'Haemoglobin is a', 'red coloured iron containing pigment present in the RBCs', ['yellow copper containing pigment in the plasma', 'white protein in the platelets', 'blue pigment in the WBCs'], 'Each haemoglobin molecule can carry a maximum of four molecules of O2.');
mc(2, 'respiratory volumes', 'The air that remains in the lungs even after a forcible expiration is the', 'residual volume', ['tidal volume', 'vital capacity', 'expiratory reserve volume'], 'The residual volume is about 1100 to 1200 mL; it can never be expelled.');
mc(2, 'regulation of respiration', 'The chemosensitive area of the respiratory centre is very sensitive to', 'CO2 and hydrogen ions', ['O2 and nitrogen', 'glucose', 'sodium ions only'], 'Increase in CO2 and H+ activates this centre, which then makes adjustments in the rhythm centre.');
mc(2, 'disorders', 'Emphysema is caused mainly by', 'cigarette smoking, which damages the alveolar walls', ['dust in a quarry', 'an inflammation of bronchi in children only', 'a lack of iron'], 'In emphysema the alveolar walls are damaged, reducing the respiratory surface. Cigarette smoking is the major cause.');

// ---- Level 3
mc(3, 'human respiratory system', 'Which of these is NOT a part of the conducting zone of the respiratory system?', 'Alveoli', ['Trachea', 'Bronchi', 'Terminal bronchioles'], 'The nose to the terminal bronchioles forms the conducting part that carries atmospheric air to the alveoli, clears it of foreign particles, humidifies it and brings it to body temperature. The alveoli are the exchange part.');
mc(3, 'human respiratory system', 'The exchange part of the respiratory system consists of', 'the alveoli and their ducts', ['the nostrils and the nasal chamber', 'the trachea and bronchi', 'the diaphragm and the ribs'], 'The alveoli are thin-walled, irregular, vascularised bag-like structures; they are the site of the actual diffusion of O2 and CO2.');
mc(3, 'human respiratory system', 'The thoracic chamber is bounded dorsally by the vertebral column, ventrally by the sternum, laterally by the ribs and on the lower side by the', 'dome-shaped diaphragm', ['pericardium', 'liver', 'small intestine'], 'It is an air-tight chamber. This anatomical setup ensures that any change in the volume of the thoracic cavity is reflected in the lung (pulmonary) cavity.');
mc(3, 'mechanism of breathing', 'During inspiration the intra-pulmonary pressure is', 'less than the atmospheric pressure', ['greater than the atmospheric pressure', 'equal to the pressure of the blood', 'zero'], 'The increase in pulmonary volume decreases the intra-pulmonary pressure below the atmospheric pressure, forcing air into the lungs.');
mc(3, 'mechanism of breathing', 'Normal expiration takes place when', 'the diaphragm and the external intercostal muscles relax', ['the diaphragm contracts', 'the internal intercostal muscles contract and the diaphragm flattens', 'the lung muscles contract'], 'Relaxation returns the diaphragm and sternum to normal positions, reducing the thoracic volume and raising the intra-pulmonary pressure above atmospheric pressure.');
mc(3, 'mechanism of breathing', 'We can increase the strength of inspiration and expiration with the help of', 'additional muscles in the abdomen', ['the cardiac muscle', 'the diaphragm of the neck', 'the muscle of the larynx'], 'Abdominal muscles help in forced expiration and in deeper inspiration.');
mc(3, 'exchange of gases', 'The partial pressure of O2 in the atmospheric air, alveoli, deoxygenated blood, oxygenated blood and tissues is closest to (in mm Hg)', '159, 104, 40, 95, 40', ['104, 159, 95, 40, 40', '159, 40, 104, 95, 40', '159, 104, 95, 40, 40'], 'The pO2 falls from 159 (air) to 104 (alveoli); deoxygenated blood is at 40; oxygenated blood leaving the lung is at 95; the tissue is at 40.', 'Alveolar air has lower pO2 than outside air.');
mc(3, 'exchange of gases', 'The partial pressure of CO2 in the atmospheric air, alveoli, deoxygenated blood, oxygenated blood and tissues is closest to (in mm Hg)', '0.3, 40, 45, 40, 45', ['40, 0.3, 45, 45, 40', '0.3, 45, 40, 45, 40', '0.3, 40, 40, 45, 45'], 'CO2 moves from the tissues (45) to the blood (45) to the alveoli (40) and to the air (0.3). The differences are small, but CO2 is highly soluble.', 'The gradient for CO2 is only 5 mm Hg.');
mc(3, 'exchange of gases', 'Even though the pressure gradient for CO2 between blood and alveoli (45 to 40 mm Hg) is small, CO2 diffuses efficiently because', 'CO2 is 20 to 25 times more soluble in the membrane than O2', ['CO2 has a higher molecular mass than O2', 'CO2 is pumped actively', 'the alveolar membrane has no layers'], 'The solubility of CO2 is 20 to 25 times higher than that of O2, so the amount of CO2 that can diffuse through the diffusion membrane per unit difference in partial pressure is much higher.');
mc(3, 'exchange of gases', 'The alveolar diffusion membrane is made of', 'thin squamous epithelium of the alveoli, endothelium of the alveolar capillaries and the basement substance between them', ['cuboidal epithelium and cartilage', 'ciliated epithelium and muscle', 'skin and bone'], 'The total thickness of the three layers is much less than a millimetre, which favours rapid diffusion.');
mc(3, 'exchange of gases', 'Which of the following does NOT affect the rate of diffusion of gases across the alveolar membrane?', 'The colour of the membrane', ['Pressure or concentration gradient', 'Solubility of the gases', 'Thickness of the membranes'], 'The rate depends on the partial pressure gradient, the solubility of gases, the thickness of the membranes involved and the surface area. NCERT lists the first three.');
mc(3, 'transport of gases', 'The percentage of CO2 carried as carbamino-haemoglobin is about', '20 to 25 per cent', ['70 per cent', '7 per cent', '97 per cent'], 'About 20-25 per cent of CO2 is carried by haemoglobin as carbamino-haemoglobin; 70 per cent is carried as bicarbonate; about 7 per cent is dissolved in plasma.');
mc(3, 'transport of gases', 'The enzyme carbonic anhydrase is present in high concentration in', 'RBCs', ['plasma', 'WBCs', 'platelets'], 'It is present in very high concentration in RBCs and in minute quantities in plasma. It facilitates the reaction between CO2 and water to form carbonic acid.');
mc(3, 'transport of gases', 'In the tissues, the reaction catalysed by carbonic anhydrase proceeds in the direction of', 'formation of carbonic acid from CO2 and water', ['formation of CO2 and water from carbonic acid', 'splitting of water', 'formation of oxyhaemoglobin'], 'High pCO2 in the tissues drives the formation of H2CO3, which dissociates to H+ and bicarbonate. At the alveoli, the reaction goes in the opposite direction.');
mc(3, 'transport of gases', 'Every 100 mL of oxygenated blood can deliver about', '5 mL of O2 to the tissues', ['20 mL of O2', '0.5 mL of O2', '50 mL of O2'], 'Under normal physiological conditions, 100 mL of oxygenated blood delivers around 5 mL of O2 to tissues.');
mc(3, 'transport of gases', 'The oxygen dissociation curve of haemoglobin is', 'sigmoid (S-shaped)', ['a straight line', 'a hyperbola', 'a parabola with a maximum'], 'A plot of percentage saturation of haemoglobin with O2 against pO2 is sigmoid. It helps to see the effect of pCO2, H+ and temperature.');
mc(3, 'transport of gases', 'Which condition in the alveoli favours the formation of oxyhaemoglobin?', 'High pO2, low pCO2, lower H+ and lower temperature', ['Low pO2, high pCO2, higher H+ and higher temperature', 'High pO2 and high pCO2', 'Low pO2 and low pCO2'], 'These conditions are present in the alveoli. The opposite conditions in the tissues favour dissociation of oxyhaemoglobin.');
mc(3, 'respiratory volumes', 'The tidal volume of a healthy man is about', '500 mL', ['1100 mL', '2500 mL', '5000 mL'], 'The tidal volume is about 500 mL, so a healthy person can inspire or expire roughly 6000 to 8000 mL of air per minute.');
mc(3, 'respiratory volumes', 'A healthy man breathing 16 times a minute with a tidal volume of 500 mL moves about how much air per minute?', '8000 mL', ['500 mL', '3200 mL', '16000 mL'], '16 x 500 = 8000 mL (8 litres) per minute. The NCERT range is 6000 to 8000 mL.');
mc(3, 'respiratory volumes', 'Which of the following is correct for the inspiratory capacity?', 'Tidal volume plus inspiratory reserve volume', ['Tidal volume plus expiratory reserve volume', 'Expiratory reserve volume plus residual volume', 'Vital capacity plus residual volume'], 'IC = TV + IRV. EC = TV + ERV. FRC = ERV + RV. TLC = VC + RV.');
mc(3, 'respiratory volumes', 'A subject has IRV = 2400 mL, TV = 450 mL and ERV = 1050 mL. The vital capacity is', '3900 mL', ['3000 mL', '2850 mL', '1500 mL'], 'VC = IRV + TV + ERV = 2400 + 450 + 1050 = 3900 mL.');
mc(3, 'respiratory volumes', 'For the same subject with a residual volume of 1150 mL, the total lung capacity is', '5050 mL', ['3900 mL', '2200 mL', '4650 mL'], 'TLC = VC + RV = 3900 + 1150 = 5050 mL.');
mc(3, 'respiratory volumes', 'For the same subject, the functional residual capacity is', '2200 mL', ['1500 mL', '2850 mL', '3900 mL'], 'FRC = ERV + RV = 1050 + 1150 = 2200 mL.');
mc(3, 'regulation of respiration', 'The pneumotaxic centre is located in the', 'pons region of the brain', ['medulla oblongata', 'cerebellum', 'hypothalamus'], 'The pneumotaxic centre in the pons moderates the functions of the respiratory rhythm centre by reducing the duration of inspiration.');
mc(3, 'regulation of respiration', 'Receptors that recognise changes in CO2 and H+ concentration in the blood are found in the', 'aortic arch and the carotid artery', ['pulmonary vein', 'hepatic portal vein', 'urinary bladder'], 'These receptors send signals to the rhythm centre in the medulla for remedial action.');
mc(3, 'disorders', 'Which of the following is an occupational respiratory disorder?', 'Silicosis caused by silica dust', ['Emphysema caused by smoking', 'Asthma caused by pollen only', 'Anaemia'], 'Long exposure to dust from grinding or stone-breaking can cause inflammation and fibrosis. Workers should wear protective masks.');
asr(3, 'human respiratory system', 'The epiglottis prevents food from entering the larynx during swallowing.', 'The epiglottis is a cartilaginous flap that covers the glottis.', 0, 'During swallowing the epiglottis covers the glottis, preventing food from entering the windpipe. R explains A.');
asr(3, 'transport of gases', 'The oxygen dissociation curve of haemoglobin is sigmoid.', 'Binding of one O2 makes the next binding easier.', 0, 'The cooperative binding of O2 molecules to the four sites of haemoglobin gives the S-shape. R explains A.');
asr(3, 'exchange of gases', 'The diffusion of O2 from alveoli to blood is rapid.', 'The diffusion membrane is made of three thin layers.', 0, 'A thin membrane (much less than a millimetre) and large surface area help diffusion. R explains A.');
asr(3, 'mechanism of breathing', 'Air flows into the lungs during inspiration.', 'The intra-pulmonary pressure is higher than the atmospheric pressure in inspiration.', 3, 'A is true. R is false: air flows in because the pulmonary pressure falls below the atmospheric pressure.', 'Air flows from high to low pressure.');
asr(3, 'regulation of respiration', 'A rise in the blood CO2 increases the breathing rate.', 'The chemosensitive area is very sensitive to CO2 and H+.', 0, 'The chemosensitive area signals the rhythm centre to adjust the rate. R explains A.');
stm(3, 'respiratory organs', 'Insects have a network of tubes called tracheal tubes.', 'In insects, the tracheae carry oxygen directly to the tissues without using blood.', 0, 'Both are correct. Tracheal tubes open to the outside through spiracles.');
stm(3, 'transport of gases', 'The binding of oxygen with haemoglobin depends mainly on the pO2.', 'The binding is not affected by pCO2 or H+.', 2, 'Statement I is correct. Statement II is wrong: pCO2, H+ concentration and temperature also affect it.');
stm(3, 'mechanism of breathing', 'During normal expiration the diaphragm relaxes.', 'The intra-pulmonary pressure falls below the atmospheric pressure in expiration.', 2, 'Statement I is correct. Statement II is wrong: in expiration the intra-pulmonary pressure is above the atmospheric pressure.');
hm(3, 'respiratory volumes', 'Consider the following. (1) TLC = VC + RV. (2) IC = TV + ERV. (3) FRC = ERV + RV. (4) EC = TV + ERV. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (3) and (4) are correct. IC = TV + IRV, so (2) is wrong.', 'Inspiratory capacity has the inspiratory reserve.');
hm(3, 'transport of gases', 'Consider the following. (1) About 70 per cent CO2 is carried as bicarbonate. (2) 97 per cent O2 is carried in the plasma. (3) Carbonic anhydrase is abundant in RBCs. (4) Each Hb carries up to 4 O2 molecules. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (3) and (4) are correct. (2) is wrong: 97 per cent of O2 is carried in RBCs as oxyhaemoglobin.');
match(3, 'respiratory organs', 'xm1', 'Animal and respiratory organ', ['A. Earthworm', 'B. Insects', 'C. Fishes', 'D. Birds'], ['p. Gills', 'q. Moist cuticle', 'r. Tracheal tubes', 's. Lungs'], 'A-q, B-r, C-p, D-s', ['A-r, B-q, C-p, D-s', 'A-q, B-r, C-s, D-p', 'A-p, B-r, C-q, D-s'], 'Earthworms: moist cuticle. Insects: tracheal tubes. Fishes: gills. Birds: lungs.');
match(3, 'respiratory volumes', 'xm2', 'Capacity and formula', ['A. Inspiratory capacity', 'B. Expiratory capacity', 'C. Functional residual capacity', 'D. Vital capacity'], ['p. TV + ERV', 'q. TV + IRV', 'r. ERV + RV', 's. ERV + TV + IRV'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], 'IC = TV + IRV; EC = TV + ERV; FRC = ERV + RV; VC = ERV + TV + IRV.');
match(3, 'transport of gases', 'xm3', 'Form of gas and percentage', ['A. O2 in RBCs as oxyhaemoglobin', 'B. O2 dissolved in plasma', 'C. CO2 as bicarbonate', 'D. CO2 as carbamino-haemoglobin'], ['p. About 3 per cent', 'q. About 97 per cent', 'r. About 70 per cent', 's. About 20 to 25 per cent'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-q, B-r, C-p, D-s'], 'Oxygen: 97 per cent in RBCs, 3 per cent in plasma. CO2: 70 per cent bicarbonate, 20 to 25 per cent carbamino-haemoglobin.');

// ---- Level 4
mc(4, 'transport of gases', 'In a person at rest, the cardiac output is 5 litres per minute. If every 100 mL of blood delivers 5 mL of O2 to the tissues, the O2 delivered per minute is', '250 mL', ['25 mL', '500 mL', '5000 mL'], '5000 mL of blood per minute = 50 units of 100 mL. 50 x 5 mL = 250 mL of O2 per minute.', 'Convert litres to mL first.');
mc(4, 'transport of gases', 'For the same person, if every 100 mL of deoxygenated blood delivers 4 mL of CO2 to the alveoli, CO2 given out per minute and the ratio of CO2 given out to O2 taken is', '200 mL and 0.8', ['400 mL and 1.6', '200 mL and 1.25', '20 mL and 0.08'], '50 x 4 = 200 mL of CO2 per minute. 200/250 = 0.8.', 'The ratio is CO2 over O2.');
mc(4, 'transport of gases', 'During heavy exercise, the cardiac output rises to 20 litres per minute and each 100 mL of blood delivers 15 mL of O2. The O2 delivered per minute is', '3000 mL', ['300 mL', '750 mL', '1500 mL'], '20000 mL is 200 units of 100 mL. 200 x 15 = 3000 mL.');
mc(4, 'transport of gases', 'The oxygen dissociation curve shifts to the right in', 'the tissues during exercise, because of the higher pCO2, H+ and temperature, which lowers the affinity of haemoglobin for O2', ['the alveoli, because of the lower pCO2', 'a cold, alkaline lung', 'the venous blood of a person at rest only'], 'In active tissues a higher temperature, higher CO2 and lower pH reduce the affinity of Hb for O2, so more O2 is released.', 'Right shift means O2 is released more easily.');
mc(4, 'transport of gases', 'Haemoglobin with a high affinity for oxygen is best expected in', 'the alveolar capillaries', ['the capillaries of a working muscle', 'a heated, acidic tissue', 'the venous blood of the vena cava'], 'Alveolar capillaries have a high pO2, low pCO2, lower H+ and lower temperature, which favour loading of O2.');
mc(4, 'transport of gases', 'Which of the following is the correct sequence of events when CO2 enters an RBC in the tissue capillary?', 'CO2 + H2O forms H2CO3 (carbonic anhydrase), then H+ and HCO3-; HCO3- leaves the RBC', ['H2CO3 splits into CO2 and water, then CO2 leaves the RBC', 'CO2 reacts with O2 to form CO', 'H+ enters the plasma and HCO3- stays in the RBC to form haemoglobin'], 'In RBCs carbonic anhydrase drives CO2 + H2O to H2CO3, which dissociates into H+ and bicarbonate. The bicarbonate is carried in the plasma; at the alveoli the reaction is reversed.');
mc(4, 'exchange of gases', 'The partial pressure of O2 in the alveoli is 104 mm Hg and in the deoxygenated blood is 40 mm Hg. The net movement of O2 is', 'from the alveoli to the blood, along a gradient of 64 mm Hg', ['from the blood to the alveoli, along 64 mm Hg', 'from the alveoli to the blood, along 144 mm Hg', 'no net movement'], 'Gases diffuse from higher to lower pressure. The difference is 104 - 40 = 64 mm Hg.');
mc(4, 'exchange of gases', 'The gradient of pCO2 between the deoxygenated blood (45 mm Hg) and the alveolar air (40 mm Hg), and the direction of net movement are', '5 mm Hg, from the blood to the alveoli', ['5 mm Hg, from the alveoli to the blood', '85 mm Hg, from the blood to the alveoli', '0 mm Hg, no movement'], '45 - 40 = 5 mm Hg, and CO2 moves from the higher to the lower pressure, from blood to alveolar air.');
mc(4, 'mechanism of breathing', 'A puncture of the chest wall lets air into the pleural cavity. The lung on that side', 'collapses and cannot follow the movement of the chest wall', ['inflates more', 'continues normally', 'gets filled with blood'], 'The air-tight pleural fluid link is broken, so the lung no longer follows the thoracic wall.');
mc(4, 'regulation of respiration', 'If the signal from the pneumotaxic centre is strengthened, the', 'duration of inspiration shortens and the respiratory rate increases', ['duration of inspiration lengthens and the rate falls', 'breathing stops', 'the chemosensitive area becomes inactive'], 'The pneumotaxic centre can reduce the duration of inspiration and thereby alter the respiratory rate.');
mc(4, 'regulation of respiration', 'Which statement about the regulation of breathing is correct?', 'The role of O2 in the regulation of respiratory rhythm is quite insignificant', ['O2 is the main stimulus for the respiratory rhythm centre', 'The rhythm centre is in the pons', 'The chemosensitive area is far from the rhythm centre'], 'The respiratory rhythm centre is in the medulla; the chemosensitive area is adjacent to it and responds to CO2 and H+.');
mc(4, 'disorders', 'In emphysema, the vital capacity is expected to', 'fall, because the alveolar walls are damaged and the lung surface is reduced', ['rise, because the lungs are larger', 'remain the same', 'rise since more air is trapped permanently'], 'Damaged alveoli reduce the respiratory surface and the capacity of the lungs.');
mc(4, 'disorders', 'Which of these is correct for asthma?', 'Inflammation of the bronchi and bronchioles causes wheezing and difficulty in breathing', ['Damage of the alveolar walls by smoking', 'Fibrosis due to stone dust', 'A deficiency of haemoglobin'], 'Asthma is a difficulty in breathing causing wheezing due to the inflammation of the bronchi and bronchioles. Emphysema involves the alveoli. Fibrosis is from dust.');
mc(4, 'respiratory volumes', 'A person breathes 12 times per minute. After training, the breathing rate is 10 per minute but the tidal volume rises from 500 mL to 700 mL. The minute volume changes from', '6000 mL to 7000 mL', ['6000 mL to 5000 mL', '5000 mL to 7000 mL', '6000 mL to 8400 mL'], '12 x 500 = 6000 mL. 10 x 700 = 7000 mL.');
mc(4, 'respiratory volumes', 'A subject has TV = 500 mL, IRV = 3000 mL, ERV = 1100 mL and RV = 1200 mL. Which of the following is correct?', 'VC = 4600 mL and TLC = 5800 mL', ['VC = 3600 mL and TLC = 4800 mL', 'VC = 4600 mL and TLC = 4600 mL', 'VC = 5800 mL and TLC = 5800 mL'], 'VC = 500 + 3000 + 1100 = 4600. TLC = VC + RV = 4600 + 1200 = 5800 mL.');
mc(4, 'respiratory volumes', 'A subject has EC = 1600 mL and IC = 3500 mL. The tidal volume is 500 mL. The vital capacity is', '4600 mL', ['5100 mL', '3500 mL', '2100 mL'], 'ERV = EC - TV = 1100; IRV = IC - TV = 3000; VC = 500 + 1100 + 3000 = 4600 mL. Alternatively VC = IC + ERV = 3500 + 1100 = 4600.');
mc(4, 'human respiratory system', 'Which one of the following is the correct sequence of the air passage in the human respiratory tract?', 'Nostrils, nasal chamber, nasopharynx, glottis, larynx, trachea, bronchi, bronchioles, alveoli', ['Nostrils, pharynx, larynx, glottis, trachea, bronchioles, bronchi, alveoli', 'Nostrils, nasal chamber, trachea, larynx, pharynx, bronchi, alveoli', 'Nostrils, larynx, nasopharynx, trachea, bronchioles, bronchi, alveoli'], 'Air passes the nasal chamber and nasopharynx through the glottis into the larynx, then the trachea, primary, secondary and tertiary bronchi, bronchioles and the alveoli.');
asr(4, 'transport of gases', 'CO2 transport as bicarbonate is quantitatively more important than by carbamino-haemoglobin.', 'About 70 per cent of CO2 is carried as bicarbonate, while 20 to 25 per cent is carried as carbamino-haemoglobin.', 0, 'The larger share (70 per cent) explains why bicarbonate is quantitatively more important.');
asr(4, 'transport of gases', 'The oxygen dissociation curve shifts to the right in active tissues.', 'High pCO2, H+ and temperature reduce the affinity of haemoglobin for oxygen.', 0, 'The right shift means less O2 is held at a given pO2, so more is released. R explains A.');
asr(4, 'regulation of respiration', 'Holding the breath for a long time makes the urge to breathe stronger.', 'The CO2 and H+ build up and stimulate the chemosensitive area.', 0, 'The rising CO2 and H+ activate the chemosensitive area, and breathing becomes inevitable. R explains A.');
asr(4, 'exchange of gases', 'The partial pressure of O2 in the alveoli is lower than in atmospheric air.', 'Alveolar air is mixed with the residual air and CO2 and water vapour.', 0, 'Atmospheric air entering the alveoli mixes with the air already there, which contains CO2 and water vapour. This lowers the pO2 to 104. R explains A.');
asr(4, 'disorders', 'Workers in stone quarries wear protective masks.', 'Long exposure to dust may cause fibrosis of the lung.', 0, 'The masks reduce inhalation of dust and thus the risk of inflammation and fibrosis. R explains A.');
stm(4, 'exchange of gases', 'The partial pressure of O2 in oxygenated blood leaving the lung is about 95 mm Hg.', 'The partial pressure of CO2 in the tissues is about 40 mm Hg.', 2, 'Statement I is correct. Statement II is wrong: the pCO2 in the tissues is about 45 mm Hg.');
stm(4, 'respiratory volumes', 'The residual volume can be measured by a simple spirometer.', 'The vital capacity can be measured by a simple spirometer.', 3, 'A spirometer measures the volumes that can be moved in and out; the residual volume remains in the lung and cannot be measured directly (Statement I incorrect). VC can be measured (Statement II correct).');
stm(4, 'transport of gases', 'Carbonic anhydrase is found in RBCs in high concentration.', 'The reaction of CO2 with water proceeds toward carbonic acid in the alveoli.', 2, 'Statement I is correct. Statement II is wrong: at the alveoli the reaction proceeds from carbonic acid to CO2 and water.');
hm(4, 'respiratory volumes', 'Consider the following. (1) RV cannot be exhaled. (2) FRC = ERV + RV. (3) VC includes RV. (4) TLC = VC + RV. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (4) are correct. (3) is wrong: VC does not include RV.');
hm(4, 'exchange of gases', 'Consider the following. (1) The diffusion membrane has three layers. (2) The CO2 solubility is higher than O2. (3) Gases move along a pressure gradient. (4) CO2 moves by active transport. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (3) are correct. (4) is wrong: gas exchange is by simple diffusion.');
match(4, 'regulation', 'xm4', 'Centre or receptor and role', ['A. Respiratory rhythm centre', 'B. Pneumotaxic centre', 'C. Chemosensitive area', 'D. Receptors in aortic arch and carotid artery'], ['p. Medulla region, sets the basic rhythm', 'q. Pons region, can shorten inspiration', 'r. Adjacent to the rhythm centre, sensitive to CO2 and H+', 's. Detect changes in CO2 and H+ in the blood'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Rhythm centre: medulla. Pneumotaxic: pons. Chemosensitive area: next to the rhythm centre. Aortic and carotid receptors detect CO2 and H+.');
match(4, 'disorders', 'xm5', 'Disorder and feature', ['A. Asthma', 'B. Emphysema', 'C. Silicosis', 'D. Asbestosis'], ['p. Inflammation of bronchi and bronchioles', 'q. Alveolar walls damaged, usually by smoking', 'r. Silica dust in stone-breaking', 's. Asbestos dust'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Asthma affects bronchi; emphysema the alveoli; silicosis is from silica dust; asbestosis is from asbestos dust.');
match(4, 'exchange of gases', 'xm6', 'Site and pO2 (mm Hg)', ['A. Atmospheric air', 'B. Alveoli', 'C. Deoxygenated blood', 'D. Oxygenated blood'], ['p. 40', 'q. 95', 'r. 104', 's. 159'], 'A-s, B-r, C-p, D-q', ['A-r, B-s, C-p, D-q', 'A-s, B-r, C-q, D-p', 'A-s, B-p, C-r, D-q'], 'Air 159, alveoli 104, deoxygenated blood 40, oxygenated blood 95.');
match(4, 'mechanism of breathing', 'xm7', 'Phase and event', ['A. Inspiration', 'B. Expiration', 'C. Diaphragm contracts', 'D. Diaphragm relaxes'], ['p. Intra-pulmonary pressure below atmospheric', 'q. Intra-pulmonary pressure above atmospheric', 'r. Thoracic volume increases', 's. Thoracic volume decreases'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'During inspiration the diaphragm contracts, the volume increases and pressure drops. In expiration the diaphragm relaxes and pressure rises.');
pass('xp1', 'Passage: a spirometer recording', 'A student breathes quietly into a spirometer. A quiet breath moves 500 mL. She then takes the deepest possible breath in, which adds 3000 mL, and then the deepest possible forced breath out, which expels a total of 1100 mL beyond the end of a quiet breath. After this, 1200 mL of air remains in her lungs.');
pq('xp1', 3, 'respiratory volumes', 'Her expiratory reserve volume is', '1100 mL', ['500 mL', '3000 mL', '1200 mL'], 'The extra air she can expel after a quiet expiration is the ERV: 1100 mL.');
pq('xp1', 4, 'respiratory volumes', 'Her vital capacity and total lung capacity are', '4600 mL and 5800 mL', ['3600 mL and 4800 mL', '4600 mL and 4600 mL', '5800 mL and 5800 mL'], 'VC = 500 + 3000 + 1100 = 4600 mL. TLC = 4600 + 1200 = 5800 mL.');
pq('xp1', 4, 'respiratory volumes', 'Her functional residual capacity is', '2300 mL', ['3500 mL', '1100 mL', '1200 mL'], 'FRC = ERV + RV = 1100 + 1200 = 2300 mL.');
pass('xp2', 'Passage: gas pressures in a resting person', 'In a resting person, the partial pressure of O2 in atmospheric air is 159 mm Hg, in alveolar air 104 mm Hg, in deoxygenated blood 40 mm Hg, in oxygenated blood 95 mm Hg and in the tissues 40 mm Hg. For CO2 the corresponding values are 0.3, 40, 45, 40 and 45 mm Hg.');
pq('xp2', 3, 'exchange of gases', 'The driving gradient for O2 at the alveolar membrane is', '64 mm Hg', ['5 mm Hg', '55 mm Hg', '119 mm Hg'], '104 - 40 = 64 mm Hg.');
pq('xp2', 4, 'exchange of gases', 'Which statement explains why CO2 moves efficiently despite its small gradient?', 'CO2 is about 20 to 25 times more soluble than O2 in the membrane', ['CO2 is actively pumped', 'CO2 has no partial pressure', 'CO2 passes through the cells without crossing the membrane'], 'The amount diffusing per unit of pressure difference is much higher for CO2.');
pass('xp3', 'Passage: an athlete at altitude', 'A sprinter runs a race. In the working muscles, the temperature rises and the blood becomes more acidic, and the pCO2 is high. Blood passing through the muscle gives up more oxygen than at rest.');
pq('xp3', 3, 'transport of gases', 'The unloading of oxygen in the muscle is helped by', 'high pCO2, high H+ and higher temperature, which lower the affinity of haemoglobin for O2', ['low pCO2 and low temperature', 'high pO2 only', 'a lower RBC count'], 'The oxygen dissociation curve shifts to the right in the muscles.');
pq('xp3', 4, 'transport of gases', 'The curve shift is', 'to the right', ['to the left', 'to the top only', 'no shift'], 'A rightward shift means that a given pO2 gives a lower percentage saturation, so more O2 is released.');
pq('xp3', 4, 'regulation of respiration', 'The breathing rate of the sprinter rises mainly because', 'the CO2 and H+ in the blood stimulate the chemosensitive area and receptors in the aortic arch and carotid artery', ['O2 is the main stimulus for the rhythm centre', 'the pneumotaxic centre stops working', 'the diaphragm becomes thicker'], 'CO2 and H+ are the main stimuli. The role of O2 is quite insignificant.');

// ---- Level 5
mc(5, 'transport of gases', 'In the tissues, the HCO3- formed in the RBC leaves the cell into the plasma. To keep electrical neutrality, which ion enters the RBC?', 'Chloride (Cl-)', ['Calcium (Ca2+)', 'Iron (Fe2+)', 'Hydrogen (H+) only'], 'Bicarbonate leaves and chloride enters (the chloride shift) so that the RBC remains electrically neutral. The idea is reversed in the lungs.', 'This is the chloride shift, an extension of the NCERT account.');
mc(5, 'exchange of gases', 'Which factor does NOT directly increase the rate of diffusion of O2 across the alveolar membrane?', 'A thicker alveolar-capillary membrane', ['A larger partial pressure gradient', 'A larger surface area of the membrane', 'Higher solubility of the gas'], 'Diffusion rate increases with gradient, area and solubility, and decreases with thickness.');
mc(5, 'respiratory volumes', 'A subject has FRC = 2300 mL, ERV = 1100 mL and TV = 500 mL. Which of the following can be correctly calculated?', 'RV = 1200 mL and EC = 1600 mL', ['RV = 3400 mL and EC = 1100 mL', 'RV = 1100 mL and EC = 500 mL', 'RV = 1200 mL and EC = 2300 mL'], 'RV = FRC - ERV = 2300 - 1100 = 1200 mL. EC = TV + ERV = 500 + 1100 = 1600 mL.');
mc(5, 'respiratory volumes', 'A breathing rate of 15 per minute, with a tidal volume of 500 mL, is changed to rapid shallow breathing of 30 per minute with a tidal volume of 250 mL. The minute volume', 'does not change, remaining at 7500 mL', ['doubles to 15000 mL', 'is halved to 3750 mL', 'rises to 11250 mL'], '15 x 500 = 7500. 30 x 250 = 7500 mL. Only the pattern changes.');
mc(5, 'mechanism of breathing', 'Which of the following would NOT increase the volume of the thoracic cavity?', 'Contraction of the internal intercostal muscles and relaxation of the diaphragm', ['Contraction of the diaphragm', 'Contraction of the external intercostal muscles', 'Raising of the sternum'], 'Contraction of the diaphragm increases the vertical dimension, and external intercostals raise the ribs and sternum. Relaxation of the diaphragm and contraction of internal intercostals decrease volume.');
mc(5, 'transport of gases', 'A chemical that blocks carbonic anhydrase in RBCs is given. The immediate effect on CO2 transport will be', 'a fall in the CO2 carried as bicarbonate, with a rise in the dissolved CO2 in the blood', ['an increase in the O2 carried by plasma', 'a complete loss of carbamino-haemoglobin', 'the stoppage of breathing in 1 second'], 'Without the enzyme, the formation of bicarbonate from CO2 is slow, so the main route (about 70 per cent) is slowed. CO2 builds up in the blood and tissues.', 'The effect is on the 70 per cent route.');
mc(5, 'regulation of respiration', 'A person has a lesion in the pons that abolishes the function of the pneumotaxic centre but the medulla is intact. Which change is expected?', 'Longer inspiration and a slower rate, since the moderating signal is lost', ['No breathing at all', 'Shorter inspiration and a faster rate', 'No change since the pons has no role'], 'The pneumotaxic centre can reduce the duration of inspiration. Without it, inspiration may be longer and the rate falls, while the rhythm centre in the medulla keeps breathing going.');
mc(5, 'disorders', 'Which of these correctly distinguishes asthma from emphysema?', 'Asthma is an inflammation of the bronchi and bronchioles; emphysema is damage to the alveolar walls with a decreased respiratory surface', ['Asthma damages alveolar walls; emphysema inflames bronchi', 'Both are due to dust in stone quarries', 'Asthma is a deficiency of haemoglobin; emphysema of vitamin A'], 'Asthma affects the airways; emphysema is a chronic disorder that reduces the surface area for gas exchange.');
asr(5, 'respiratory volumes', 'The functional residual capacity is the volume that stays in the lungs after a normal, quiet expiration.', 'FRC is the sum of the ERV and the RV.', 0, 'After a quiet expiration, the air left is what could still be expelled (ERV) plus what can never be expelled (RV). R explains A.');
asr(5, 'transport of gases', 'In the alveolar capillaries the reaction of carbonic acid goes toward CO2 and water.', 'The pCO2 in the alveoli is lower than in the blood.', 0, 'Low pCO2 favours the removal of CO2 and the reverse reaction. R explains A.');
asr(5, 'exchange of gases', 'The pO2 in the tissues is 40 mm Hg and in the oxygenated blood is 95 mm Hg, so O2 diffuses to the tissues.', 'Gases diffuse from regions of higher partial pressure to regions of lower partial pressure.', 0, 'The O2 gradient of 55 mm Hg drives diffusion into the tissue. R explains A.');
stm(5, 'transport of gases', 'In exercise, the haemoglobin releases more oxygen per 100 mL of blood than at rest.', 'The oxygen dissociation curve shifts to the left during exercise.', 2, 'Statement I is correct. Statement II is wrong: the shift is to the right.');
stm(5, 'respiratory volumes', 'The vital capacity is always smaller than the total lung capacity.', 'The difference between them equals the residual volume.', 0, 'TLC = VC + RV, so VC is smaller by exactly RV. Both are correct.');
hm(5, 'mechanism of breathing', 'Consider the following. (1) The diaphragm contracts in inspiration. (2) The external intercostals contract in inspiration. (3) The intra-pulmonary pressure rises in inspiration. (4) The thoracic volume decreases in expiration. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (4) are correct. (3) is wrong: pressure falls in inspiration.');
hm(5, 'respiratory organs', 'Consider these animals and their respiratory organs. (1) Prawn : gills (2) Cockroach : tracheae (3) Earthworm : moist cuticle (4) Frog : gills as an adult. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (3) are correct. An adult frog uses lungs and moist skin, not gills (tadpoles have gills).', 'Tadpole and adult differ.');
match(5, 'respiratory volumes', 'xm8', 'Volume and typical value in a healthy adult', ['A. Tidal volume', 'B. Inspiratory reserve volume', 'C. Expiratory reserve volume', 'D. Residual volume'], ['p. 500 mL', 'q. 2500 to 3000 mL', 'r. 1000 to 1100 mL', 's. 1100 to 1200 mL'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-p, B-r, C-q, D-s'], 'TV about 500 mL; IRV 2500 to 3000 mL; ERV 1000 to 1100 mL; RV 1100 to 1200 mL.', 'ERV and RV values are close; do not swap.');
pq('xp2', 4, 'exchange of gases', 'The driving gradient for O2 from the oxygenated blood to the tissues is', '55 mm Hg', ['64 mm Hg', '5 mm Hg', '95 mm Hg'], '95 - 40 = 55 mm Hg.', 'Use the oxygenated blood value, not the alveolar one.');
mc(4, 'respiratory organs', 'Which pair of animal and respiratory organ is NOT correct?', 'Prawn : tracheal tubes', ['Frog : lungs and moist skin', 'Cockroach : tracheae', 'Fish : gills'], 'A prawn is an aquatic arthropod and breathes by gills. Cockroaches (insects) use tracheae; frogs use lungs and skin; fishes use gills.');
match(3, 'human respiratory system', 'xm9', 'Part and function', ['A. Epiglottis', 'B. Larynx', 'C. Pleura', 'D. Alveoli'], ['p. Covers the glottis during swallowing', 'q. Sound production', 'r. Double-layered covering of the lung with fluid between', 's. Site of exchange of gases'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'The epiglottis covers the glottis; the larynx is the sound box; the pleura covers the lungs; the alveoli are the sites of diffusion.');
match(4, 'transport of gases', 'xm10', 'Process and where it happens', ['A. Loading of O2 on haemoglobin', 'B. Unloading of O2 to cells', 'C. Action of carbonic anhydrase', 'D. Rhythm centre'], ['p. Alveolar capillaries', 'q. Tissue capillaries and tissues', 'r. Inside RBCs', 's. Medulla'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Loading is at the alveolar capillaries; unloading is at the tissues; carbonic anhydrase is in RBCs; the rhythm centre is in the medulla.');

export default { topic: 'breathing', groups, items, gens };
